// CS0169/CS0649: fields generated by XAML binding, not used directly in code — harmless
#pragma warning disable CS0169, CS0649
using System;
using SMDWin.Views;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using PdfSharp.Drawing;
using PdfSharp.Pdf;
using System.ServiceProcess;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Animation;
using System.Windows.Threading;
using WpfPath = System.Windows.Shapes.Path;
using SMDWin;
using SMDWin.Models;
using SMDWin.Services;
using Forms = System.Windows.Forms;

// Resolve WinForms vs WPF ambiguities
using Application      = System.Windows.Application;
using MessageBox       = System.Windows.MessageBox;
using MessageBoxButton = System.Windows.MessageBoxButton;
using MessageBoxImage  = System.Windows.MessageBoxImage;
using MessageBoxResult = System.Windows.MessageBoxResult;
using SaveFileDialog   = Microsoft.Win32.SaveFileDialog;
using ToolTip          = System.Windows.Controls.ToolTip;
using OpenFileDialog   = Microsoft.Win32.OpenFileDialog;
using Button           = System.Windows.Controls.Button;
using Brush            = System.Windows.Media.Brush;
using WpfColor         = System.Windows.Media.Color;
using WpfColorConv     = System.Windows.Media.ColorConverter;

namespace SMDWin.Views
{
    public partial class MainWindow
    {
        private async void OnTempTick(object? sender, EventArgs e)
        {
            if (_monitoringPausedForScan) return;

            SMDWin.Services.UiStallLogger.Mark("TempTick:start");
            UpdateStressTimers();
            TickStressPlan();   // the time on the "Stop" button
            UpdateStressFx();   // the glow around the dials and the progress line while a test runs
            SMDWin.Services.UiStallLogger.Mark("TempTick:stressTimers");
            AutoClearTempBadgeIfStale();
            AdvanceTaskBadgeAnim();
            SMDWin.Services.UiStallLogger.Mark("TempTick:badges");
            _ = RefreshDiskTemperaturesIfDueAsync();
            SMDWin.Services.UiStallLogger.Mark("TempTick:diskTemps");

            // With the window hidden the rate comes from the timer interval (ApplySensorCadence), not from skipped ticks
            bool windowHidden = IsUiHidden;
            var bgRec = BgRec;
            int actSteps = ComputeActivityCatchUpSteps(windowHidden);

            // Performance: WifiReader.Read() (native WLAN API) and GetSystemDiskIO() (PerformanceCounter.NextValue()) touch no WPF
            // elements — they run on a background thread; the rest of the method continues on the UI thread after the await.
            SMDWin.Services.WifiInfo? wifiResult = null;
            bool pollWifi = (DateTime.UtcNow - _lastWifiPoll).TotalSeconds >= 10;
            float sdrU = 0, sdwU = 0;
            Exception? wifiEx = null, diskIoEx = null;
            await Task.Run(() =>
            {
                if (pollWifi)
                {
                    try { wifiResult = SMDWin.Services.WifiReader.Read(); }
                    catch (Exception ex) { wifiEx = ex; }
                }
                try { GetSystemDiskIO(out sdrU, out sdwU); }
                catch (Exception ex) { diskIoEx = ex; }
                try { SamplePerDiskActivity(); }   // each disk separately, for the charts in the Storage disk cards
                catch (Exception ex) { diskIoEx ??= ex; }
            });
            SMDWin.Services.UiStallLogger.Mark("TempTick:after-io");
            if (wifiEx != null) AppLogger.Debug(wifiEx.Message);
            if (diskIoEx != null) AppLogger.Debug(diskIoEx.Message);
            try { PushPerDiskActivity(actSteps); } catch (Exception ex) { AppLogger.Debug($"PushPerDiskActivity: {ex.Message}"); }

            try
            {
                if (pollWifi)
                {
                    _lastWifiPoll = DateTime.UtcNow;
                    if (wifiResult != null) _lastWifi = wifiResult;
                }
                var _trafficU = _netTrafficSvc.GetCurrentTraffic();
                if (_trafficU.Count > 0)
                {
                    // the sum of the physical adapters ONLY — a Hyper-V/VMware/VPN adapter would otherwise double the traffic of the same
                    // physical connection on the Dashboard.
                    var (totalSend, totalRecv) = SMDWin.Services.NetworkTrafficSampler.GetPhysicalTotal();
                    _emaNetDown = (float)totalRecv;
                    _emaNetUp   = (float)totalSend;
                    // The name: the first adapter with real traffic, or the first in the list.
                    // Adapter name: Total when several are active, or the exact name
                    var primary = _trafficU.FirstOrDefault(t => t.RecvKBs > 0 || t.SendKBs > 0)
                                  ?? _trafficU[0];
                    _lastNetAdapterName = _trafficU.Count > 1
                        ? $"Total ({_trafficU.Count} adapters)"
                        : primary.Name;
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try
            {
                _emaDiskRead  = sdrU;
                _emaDiskWrite = sdwU;
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            try
            {
                float nd = Math.Max(0f, _emaNetDown);
                float nu = Math.Max(0f, _emaNetUp);
                _rolNetDownOvrl[_rolNetOvrlIdx % 5] = nd;
                _rolNetUpOvrl[_rolNetOvrlIdx % 5]   = nu;
                _rolNetOvrlIdx++;
                _rolNetOvrlCnt = Math.Min(_rolNetOvrlCnt + 1, 5);
                float sumD = 0f, sumU = 0f;
                for (int i = 0; i < _rolNetOvrlCnt; i++) { sumD += _rolNetDownOvrl[i]; sumU += _rolNetUpOvrl[i]; }
                for (int a = 0; a < actSteps; a++)
                {
                    _netOverviewDown.Push(sumD / _rolNetOvrlCnt);
                    _netOverviewUp.Push(sumU / _rolNetOvrlCnt);
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            // STORAGE-ACTIVITY-CHART: a rolling Read/Write buffer for the live chart on the Storage page.
            try
            {
                _diskWarmupTicksStorage++;
                if (_diskWarmupTicksStorage > 3)
                {
                    float dr = Math.Min(Math.Max(0f, _emaDiskRead),  4_000_000f);
                    float dw = Math.Min(Math.Max(0f, _emaDiskWrite), 4_000_000f);
                    float curAvgR = 0f; for (int i = 0; i < _rolDiskCntStorage; i++) curAvgR += _rolDiskRStorage[i];
                    if (_rolDiskCntStorage > 0) curAvgR /= _rolDiskCntStorage;
                    float curAvgW = 0f; for (int i = 0; i < _rolDiskCntStorage; i++) curAvgW += _rolDiskWStorage[i];
                    if (_rolDiskCntStorage > 0) curAvgW /= _rolDiskCntStorage;
                    if (dr > curAvgR * 1.25f && dr - curAvgR > 10_240f)
                        for (int i = 0; i < 5; i++) _rolDiskRStorage[i] = dr;
                    if (dw > curAvgW * 1.25f && dw - curAvgW > 10_240f)
                        for (int i = 0; i < 5; i++) _rolDiskWStorage[i] = dw;
                    _rolDiskRStorage[_rolDiskIdxStorage % 5] = dr;
                    _rolDiskWStorage[_rolDiskIdxStorage % 5] = dw;
                    _rolDiskIdxStorage++;
                    _rolDiskCntStorage = Math.Min(_rolDiskCntStorage + 1, 5);
                    float sumR = 0f, sumW = 0f;
                    for (int i = 0; i < _rolDiskCntStorage; i++) { sumR += _rolDiskRStorage[i]; sumW += _rolDiskWStorage[i]; }
                    for (int a = 0; a < actSteps; a++)
                    {
                        _storageActR.Push(sumR / _rolDiskCntStorage);
                        _storageActW.Push(sumW / _rolDiskCntStorage);
                        _storageActLatency.Push(_lastDiskAvgMs);
                    }
                    UpdateStorageActivityCard(sumR / _rolDiskCntStorage, sumW / _rolDiskCntStorage, _lastDiskAvgMs, actSteps); // the shared card
                }
                // during warmup do not push a false 0 — as on the Dashboard, skip the push

                if (_currentPanel == "Disk" && !windowHidden)
                {
                    try { DrawStorageActivityChart();      } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                    try { DrawBenchDiskActivityChart();    } catch (Exception ex3) { AppLogger.Debug(ex3.Message); }
                    try { DrawSurfaceDiskActivityChart();  } catch (Exception ex4) { AppLogger.Debug(ex4.Message); }
                    try { DrawSmartDiskActivityChart();    } catch (Exception ex5) { AppLogger.Debug(ex5.Message); }
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            SMDWin.Services.UiStallLogger.Mark("TempTick:activity");
            try { UpdateDashboardLiveCards(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            SMDWin.Services.UiStallLogger.Mark("TempTick:dashLive");

            bool needFullRead = _currentPanel is "Dashboard" or "Stress" or "Hardware"
                                or "Processes" or "Network" or "Disk" or "Ram" or "Tools" or "";

            _sensorLiveMaxAge = (needFullRead && !windowHidden)
                ? SMDWin.Services.SensorValidation.MaxLiveAge(_tempTimer.Interval)
                : TimeSpan.FromSeconds(35);   // pages without sensors / hidden window: a rare read, on purpose

            // Active widget / tray sensors = someone shows live temperatures, so the full read can no longer wait 15 s (on Settings
            // or with the window in the tray, the widget would stay on "--" until the next full read).
            bool liveConsumers = _compactWidget != null || _traySensorIcons.Count > 0;
            double fullReadGapMs = OffPageFullReadGapMs(liveConsumers);
            if (!needFullRead && (DateTime.UtcNow - _lastFullSensorReadUtc).TotalMilliseconds > fullReadGapMs)
                needFullRead = true;

            // The CPU temperature is still missing after start-up (LHM warm-up) -> full read immediately
            if (!needFullRead && liveConsumers && _tempReader != null
                && _lastTempSnapRaw != null && !_lastTempSnapRaw.CpuTemp.HasValue
                && _cpuTempWarmupForced < CpuTempWarmupMaxForced)
            {
                _cpuTempWarmupForced++;
                needFullRead = true;
            }

            if (!needFullRead)
            {
                _tempThrottleSkip = (_tempThrottleSkip + 1) % 2;
                if (_tempThrottleSkip != 0) return;

                float vCpu = _lastTempSnap?.CpuTemp ?? float.NaN;
                float vGpu = _lastTempSnap?.GpuTemp ?? float.NaN;
                float vCpuFreq = _lastTempSnap?.CpuFreqMHz ?? (_lastCpuFreqMHz > 0 ? _lastCpuFreqMHz : float.NaN);
                float vCpuUsage = _cachedCpuPct >= 0 ? _cachedCpuPct : float.NaN;
                float vRamUsage = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                    ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f) : float.NaN;
                float vCpuPower = _lastTempSnap?.CpuPowerW ?? float.NaN;
                float vGpuLoad = GpuLoadNow ?? float.NaN;
                float vGpuFreq = _lastTempSnap?.GpuFreqMHz ?? float.NaN;
                float vGpuVram = _lastTempSnap?.GpuMemUsedMB ?? float.NaN;
                float vGpuPower = _lastTempSnap?.GpuPowerW ?? float.NaN;
                float vCpuVCore = _lastTempSnap?.CpuVCoreV ?? float.NaN;
                float vGpuMemFreq = _lastTempSnap?.GpuMemFreqMHz ?? float.NaN;
                float vSysPower = ComputeSystemPowerW(_lastTempSnap?.CpuPowerW, _lastTempSnap?.GpuPowerW,
                    _lastTempSnap?.BatteryLiveW, _summary?.HasBattery == true);

                // Reduced: nothing to write now — the next full read joins the interval with a line.
                // Off: the interval without reads stays empty, with the known value only on a real catch-up.
                if (bgRec == BgRecMode.Off)
                {
                    int stepsThrottled = ComputeChartCatchUpSteps();
                    float prevWrittenCpu = _chartCpu[(_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints];
                    bool sameAsLastWrite = !float.IsNaN(prevWrittenCpu) && !float.IsNaN(vCpu) && prevWrittenCpu == vCpu;
                    int realSlots = stepsThrottled <= 2 && sameAsLastWrite
                        ? 0
                        : Math.Min(stepsThrottled, ChartCatchUpRealSlots);
                    int gapSlots = stepsThrottled - realSlots;
                    var cached = new[]
                    {
                        vCpu, vGpu, vCpuFreq, vCpuUsage, vRamUsage, vCpuPower, vGpuLoad, vGpuFreq, vGpuVram,
                        vGpuPower, vCpuVCore, vGpuMemFreq, vSysPower, CurrentDiskTempForChart(), vGpuLoad,
                    };
                    if (gapSlots > 0)
                    {
                        PushChartSample(gapSlots, cached, gap: true);
                        // PushChartSample puts the value on the last step; here the whole interval is empty
                        int lastGapIdx = (_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints;
                        foreach (var arr in StressChartSeries()) arr[lastGapIdx] = float.NaN;
                    }
                    for (int r = 0; r < realSlots; r++) PushChartSample(1, cached, gap: false);
                }

                // Still push cached data to compact widget
                if (_compactWidget != null)
                {
                    float ramPct = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                        ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f)
                        : -1f;
                    int didx = (_chartIdx > 0 ? _chartIdx - 1 : 0) % ChartMaxPoints;
                    _compactWidget.PushData(
                        cpuPct: _cachedCpuPct, gpuPct: _cachedGpuPct, ramPct: ramPct,
                        netUp: _emaNetUp, netDown: _emaNetDown,
                        diskRead: _dashDiskRead[didx], diskWrite: _dashDiskWrite[didx],
                        cpuTemp: _lastTempSnap?.CpuTemp, gpuTemp: _lastTempSnap?.GpuTemp,
                        cpuFreqMHz: _lastTempSnap?.CpuFreqMHz);
                }

                if (_traySensorIcons.Count > 0)
                {
                    float ramPctT = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                        ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f)
                        : -1f;
                    try
                    {
                        UpdateTraySensorIcons(
                            cpuPct: _cachedCpuPct, gpuPct: _cachedGpuPct, ramPct: ramPctT,
                            cpuTemp: _lastTempSnap?.CpuTemp, gpuTemp: _lastTempSnap?.GpuTemp,
                            cpuFreqMHz: _lastTempSnap?.CpuFreqMHz ?? (_lastCpuFreqMHz > 0 ? _lastCpuFreqMHz : (float?)null));
                    }
                    catch (Exception exT) { AppLogger.Debug($"Tray throttled update: {exT.Message}"); }
                }
                return;
            }

            if (_tempTickBusy) return;   // an LHM read is still in flight — the charts keep going anyway
            _tempTickBusy = true;
            try
            {

            if (_tempReader == null) return;

            try { _tempReader.StressActive = _cpuStress.Running || _gpuStress.IsRunning; }
            catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); /* stress services may not be initialized yet on the first tick */ }

            var snapReader = _tempReader; // capture local ref — avoids race with reinit
            var _swRead = System.Diagnostics.Stopwatch.StartNew();

            // Hard timeout: if LHM hangs >10s, return the old data and continue
            TempSnapshot? snap = null;
            var readTask = Task.Run(() => snapReader.Read());
            var timeoutTask = Task.Delay(TimeSpan.FromSeconds(10));
            var firstDone = await Task.WhenAny(readTask, timeoutTask);
            if (firstDone == readTask)
            {
                try { snap = await readTask; }
                catch (Exception ex)
                {
                    AppLogger.Warning(ex, "LHM Read faulted");
                    snap = _lastTempSnapRaw;
                }
            }
            else
            {
                AppLogger.Info($"LHM Read timeout >10s (real race, not just a decorative CancellationToken) — using old data (panel={_currentPanel})");
                snap = _lastTempSnapRaw; // the previous data — its age decides whether it is still shown
                // The orphaned task keeps running in the background (it cannot be stopped, it is external synchronous code) — only
                // catch the exception so it does not become an UnobservedTaskException.
                _ = readTask.ContinueWith(
                    t => { if (t.Exception != null) AppLogger.Debug($"Orphaned LHM read faulted: {t.Exception.Message}"); },
                    TaskScheduler.Default);
            }

            if (snapReader.IsProbablyHung && !_tempReaderRecoveryInFlight)
            {
                _tempReaderRecoveryInFlight = true;
                AppLogger.Warning("FREEZE-RECOVERY: the native LHM read seems blocked for good — creating a completely new TempReader and abandoning the old object.");
                var hung = snapReader;
                _ = Task.Run(() =>
                {
                    try
                    {
                        var fresh = new SMDWin.Services.TempReader();
                        fresh.StressActive = hung.StressActive;
                        _tempReader = fresh;   // atomic swap (reference) — the next tick uses it
                        AppLogger.Info("FREEZE-RECOVERY: new TempReader active. Trying a best-effort Close on the old one (dedicated thread, may stay blocked — fine, it is background).");
                        var closer = new System.Threading.Thread(() =>
                        {
                            try { hung.AbandonClose(); AppLogger.Info("FREEZE-RECOVERY: the old object still closed cleanly."); }
                            catch (Exception ex2) { AppLogger.Debug($"FREEZE-RECOVERY close old: {ex2.Message}"); }
                        }) { IsBackground = true, Name = "TempReaderAbandonedCloser" };
                        closer.Start();
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "FREEZE-RECOVERY failed"); }
                    finally { _tempReaderRecoveryInFlight = false; }
                });
            }

            _swRead.Stop();
            long readMs = _swRead.ElapsedMilliseconds;
            if (readMs > 15000)
            {
                AppLogger.Info($"LHM Read: {readMs}ms elapsed, but over the 10s hard timeout — probably a system sleep/resume artefact, not real slowness (panel={_currentPanel})");
            }
            else if (readMs > 800)
                AppLogger.Info($"LHM Read slow: {readMs}ms (panel={_currentPanel})");
            NoteSensorReadMs(readMs);
            if (_tempTimer != null)
            {
                // a slow read thins out the rate; otherwise it stays the Settings one (visible) or the background one (hidden)
                double slowMs =
                    readMs > 4000 ?  5000 :
                    readMs > 2000 ?  3000 :
                    readMs > 1000 ?  2000 :
                    readMs >  500 ?  1500 : 0;
                double target = windowHidden
                    ? Math.Max(HiddenSensorIntervalMs(), slowMs)
                    : Math.Max(UserSensorIntervalMs(), slowMs);
                if (Math.Abs(_tempTimer.Interval.TotalMilliseconds - target) > 1)
                    _tempTimer.Interval = TimeSpan.FromMilliseconds(target);
            }
            if (snap == null) return; // reader not yet initialized

            // ONLY a snapshot newer than the existing one is accepted as a "new read".
            // A timeout / busy lock returns the old snapshot — it does NOT reset the read clock and does not become "fresh" through
            // simple reassignment.
            var prevRaw = _lastTempSnapRaw;
            if (prevRaw == null || snap.CapturedUtc > prevRaw.CapturedUtc)
            {
                _lastTempSnapRaw = snap;
                if (snap.CapturedUtc != DateTime.MinValue) _lastFullSensorReadUtc = snap.CapturedUtc;
            }
            SMDWin.Services.UiStallLogger.Mark("TempTick:after-read");
            UpdateSensorStaleState();
            snap = _lastTempSnap;   // fresh or without values, never old data presented as live
            if (snap == null) return;

            // Session history — one sample every 5s from app start, for the PDF full-session charts
            var histNow = DateTime.Now;
            TrackStressSpan(histNow);
            if ((histNow - _sessHistLastSample).TotalSeconds >= 5)
            {
                _sessHistLastSample = histNow;
                lock (_sessHist)
                {
                    _sessHist.Add((
                        histNow,
                        snap.CpuTemp    ?? float.NaN,
                        snap.GpuTemp    ?? float.NaN,
                        _cachedCpuPct >= 0 ? _cachedCpuPct : float.NaN,
                        GpuLoadNow ?? float.NaN));
                    // Cap memory: at 5s/sample, 17280 = 24h. Beyond that drop oldest.
                    if (_sessHist.Count > 17280) _sessHist.RemoveAt(0);
                }
            }
            try
            {

                // Update tray icon with current CPU temp + load
                UpdateTrayIcon(snap.CpuTemp, CpuLoadNow);

                string FmtTemp(float v) => $"{TempUnit.Fmt(v)}";   // compact: "74°C" instead of "74"
                string FmtPct(float v)  => $"{v:F0}%";   // compact: "82%" instead of "82"

                // GPU Temp
                if (snap.GpuTemp.HasValue && snap.GpuTemp.Value > 0)
                {
                    float gt = snap.GpuTemp.Value;
                    if (gt < _gpuTempMin) _gpuTempMin = gt;
                    if (gt > _gpuTempMax) _gpuTempMax = gt;
                    _gpuTempSum += gt; _gpuTempCnt++;
                    if (FindName("TxtGpuTempMin") is TextBlock gtMin) gtMin.Text = FmtTemp(_gpuTempMin);
                    if (FindName("TxtGpuTempMax") is TextBlock gtMax) { gtMax.Text = FmtTemp(_gpuTempMax); gtMax.Foreground = _gpuTempMax > 90 ? _brRed : _gpuTempMax > 75 ? _brOrange : _brGreen; }
                    if (FindName("TxtGpuTempAvg") is TextBlock gtAvg) gtAvg.Text = FmtTemp(_gpuTempSum / _gpuTempCnt);
                }
                // CPU Load
                if (_cachedCpuPct >= 0)
                {
                    float cl = _cachedCpuPct;
                    if (cl < _cpuLoadMin) _cpuLoadMin = cl;
                    if (cl > _cpuLoadMax) _cpuLoadMax = cl;
                    _cpuLoadSum += cl; _cpuLoadCnt++;
                    if (FindName("TxtCpuLoadMin") is TextBlock clMin) clMin.Text = FmtPct(_cpuLoadMin);
                    if (FindName("TxtCpuLoadMax") is TextBlock clMax) { clMax.Text = FmtPct(_cpuLoadMax); clMax.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush"); }
                    if (FindName("TxtCpuLoadAvg") is TextBlock clAvg && _cpuLoadCnt > 0) clAvg.Text = FmtPct(_cpuLoadSum / _cpuLoadCnt);
                    if (FindName("TxtCpuLoadMin_c") is TextBlock clMinC) clMinC.Text = FmtPct(_cpuLoadMin);
                    if (FindName("TxtCpuLoadMax_c") is TextBlock clMaxC) { clMaxC.Text = FmtPct(_cpuLoadMax); clMaxC.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush"); }
                    if (FindName("TxtCpuLoadAvg_c") is TextBlock clAvgC && _cpuLoadCnt > 0) clAvgC.Text = FmtPct(_cpuLoadSum / _cpuLoadCnt);
                }
                // GPU Load
                if (GpuLoadNow is float gl)
                {
                    if (gl < _gpuLoadMin) _gpuLoadMin = gl;
                    if (gl > _gpuLoadMax) _gpuLoadMax = gl;
                    _gpuLoadSum += gl; _gpuLoadCnt++;
                    if (FindName("TxtGpuLoadMin") is TextBlock glMin2) glMin2.Text = FmtPct(_gpuLoadMin);
                    if (FindName("TxtGpuLoadMax") is TextBlock glMax) { glMax.Text = FmtPct(_gpuLoadMax); glMax.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush"); }
                    if (FindName("TxtGpuLoadAvg") is TextBlock glAvg && _gpuLoadCnt > 0) glAvg.Text = FmtPct(_gpuLoadSum / _gpuLoadCnt);
                }
                // RAM
                if (_cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0)
                {
                    float rl = Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f);
                    if (rl < _ramLoadMin) _ramLoadMin = rl;
                    if (rl > _ramLoadMax) _ramLoadMax = rl;
                    _ramLoadSum += rl; _ramLoadCnt++;
                    if (FindName("TxtRamLoadMin") is TextBlock rlMin) rlMin.Text = FmtPct(_ramLoadMin);
                    if (FindName("TxtRamLoadMax") is TextBlock rlMax) rlMax.Text = FmtPct(_ramLoadMax);
                    if (FindName("TxtRamLoadAvg") is TextBlock rlAvg && _ramLoadCnt > 0) rlAvg.Text = FmtPct(_ramLoadSum / _ramLoadCnt);
                }

                // CPU Temp Min/Max/Avg — display in tabel
                if (_cpuMin.HasValue && FindName("TxtCpuTempMin") is TextBlock ctMin) ctMin.Text = FmtTemp(_cpuMin.Value);
                if (_cpuMax.HasValue && FindName("TxtCpuTempMax") is TextBlock ctMax) { ctMax.Text = FmtTemp(_cpuMax.Value); ctMax.Foreground = _cpuMax.Value > 85 ? _brRed : _cpuMax.Value > 70 ? _brOrange : _brGreen; }
                // CPU Temp Avg — computed from the _chartCpu buffer
                if (_cpuMin.HasValue && _cpuMax.HasValue && FindName("TxtCpuTempAvg") is TextBlock ctAvg)
                {
                    float sum = 0; int cnt = 0;
                    int n = Math.Min(_chartIdx, ChartMaxPoints);
                    for (int k = 0; k < n; k++) { float v = _chartCpu[(_chartIdx - 1 - k + ChartMaxPoints) % ChartMaxPoints]; if (!float.IsNaN(v) && v > 0) { sum += v; cnt++; } if (cnt >= 300) break; } // max 5 min
                    if (cnt > 0) ctAvg.Text = FmtTemp(sum / cnt);
                }
                UpdateStressTempLabel(TxtStressGpuTemp, TxtStressGpuMM, snap.GpuTemp, ref _gpuMin, ref _gpuMax);
                UpdateStressCards(snap); // the CPU / GPU cards (MainWindow.StressCards.cs)

                if (FindName("RowIntegratedGpu") is Grid rowIgpu)
                {
                    if (snap.HasIntegratedGpu)
                    {
                        rowIgpu.Visibility = Visibility.Visible;
                        if (FindName("TxtIntegratedGpuName") is TextBlock igpuName)
                            igpuName.Text = string.IsNullOrWhiteSpace(snap.IntegratedGpuName) || snap.IntegratedGpuName == "--"
                                ? "iGPU" : snap.IntegratedGpuName;
                        if (FindName("TxtIntegratedGpuValues") is TextBlock igpuVals)
                        {
                            string tempStr = snap.IntegratedGpuTemp.HasValue ? $"{TempUnit.Fmt(snap.IntegratedGpuTemp.Value)}" : "—";
                            string loadStr = snap.IntegratedGpuLoadPct.HasValue ? $"{snap.IntegratedGpuLoadPct.Value:F0}%" : "—";
                            igpuVals.Text = $"{tempStr}  /  {loadStr}";
                        }
                    }
                    else
                    {
                        rowIgpu.Visibility = Visibility.Collapsed;
                    }
                }
                // CPU Temp "Now" column
                if (snap.CpuTemp.HasValue && snap.CpuTemp.Value > 0)
                {
                    float cpuNow = snap.CpuTemp.Value;
                    var cpuNowColor = cpuNow > 85f ? WpfColor.FromRgb(239,68,68)
                                    : cpuNow > 70f ? WpfColor.FromRgb(251,146,60)
                                    :                WpfColor.FromRgb(34,197,94);
                    if (FindName("TxtStressCpuTemp") is TextBlock tstCpu)
                    {
                        tstCpu.Text       = $"{TempUnit.Fmt(cpuNow)}";
                        tstCpu.Foreground = new SolidColorBrush(cpuNowColor);
                    }
                    // Also update Min/Max for the CPU (if TxtStressCpuMM exists)
                    _cpuMin = _cpuMin.HasValue ? Math.Min(_cpuMin.Value, cpuNow) : cpuNow;
                    _cpuMax = _cpuMax.HasValue ? Math.Max(_cpuMax.Value, cpuNow) : cpuNow;
                    if (FindName("TxtStressCpuMM") is TextBlock tstCpuMM)
                        tstCpuMM.Text = $"Min {TempUnit.Fmt(_cpuMin)}  /  Max {TempUnit.Fmt(_cpuMax)}";
                }
                if (FindName("TxtStressGpuTempHeader") is System.Windows.Controls.TextBlock gtH2 && snap.GpuTemp.HasValue)
                    gtH2.Text = $"{snap.GpuTemp.Value:F0}";
                if (snap.CpuTemp.HasValue)
                {
                    float ct = snap.CpuTemp.Value;
                    var ctColor = ct > 85 ? WpfColor.FromRgb(239,68,68) : ct > 70 ? WpfColor.FromRgb(251,146,60) : WpfColor.FromRgb(59,130,246);
                    if (FindName("TxtStressCpuTempLive") is System.Windows.Controls.TextBlock ctl) { ctl.Text = $"{ct:F0}"; ctl.Foreground = new System.Windows.Media.SolidColorBrush(ctColor); }
                    if (FindName("TxtStressCpuTempLive2") is System.Windows.Controls.TextBlock ctl2) { ctl2.Text = $"{TempUnit.Fmt(ct)}"; ctl2.Foreground = new System.Windows.Media.SolidColorBrush(ctColor); }
                    if (FindName("TxtStressCpuFreqOverlay") is System.Windows.Controls.TextBlock cfo) cfo.Text = snap.CpuFreqMHz.HasValue ? (snap.CpuFreqMHz.Value >= 1000 ? $"{snap.CpuFreqMHz.Value/1000f:F2} GHz" : $"{snap.CpuFreqMHz.Value:F0} MHz") : "—";
                    if (FindName("TxtStressCpuLoadOverlay") is System.Windows.Controls.TextBlock clo) clo.Text = _cachedCpuPct >= 0 ? $"{_cachedCpuPct:F0}%" : "—";
                    if (FindName("TxtStressVCoreOverlay") is System.Windows.Controls.TextBlock vco) vco.Text = snap.CpuVCoreV.HasValue ? $"VCore {snap.CpuVCoreV.Value:F3} V" : "";
                }
                if (snap.GpuTemp.HasValue)
                {
                    float gt = snap.GpuTemp.Value;
                    var gtColor = gt > 85 ? WpfColor.FromRgb(239,68,68) : WpfColor.FromRgb(234,88,12);
                    if (FindName("TxtStressGpuTempLive") is System.Windows.Controls.TextBlock gtl) { gtl.Text = $"{gt:F0}"; gtl.Foreground = new System.Windows.Media.SolidColorBrush(gtColor); }
                    if (FindName("TxtStressVramOverlay") is System.Windows.Controls.TextBlock vov) vov.Text = snap.GpuMemUsedMB.HasValue ? $"{snap.GpuMemUsedMB.Value:F0} MB VRAM" : "—";
                    if (FindName("TxtStressGpuFreqOverlay") is System.Windows.Controls.TextBlock gfo) gfo.Text = snap.GpuFreqMHz.HasValue ? $"{snap.GpuFreqMHz.Value:F0} MHz" : "—";
                    if (FindName("TxtStressGpuLoadPct") is System.Windows.Controls.TextBlock sglp) sglp.Text = GpuLoadNow is float sgl ? $"{sgl:F0}%" : "—";
                    if (FindName("TxtStressVramBadge") is System.Windows.Controls.TextBlock vbadge) vbadge.Text = snap.GpuMemUsedMB.HasValue ? $"{snap.GpuMemUsedMB.Value:F0} MB" : "";
                }

                try
                {
                    int gidxS = (_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints;
                    float gpuForChartS;
                    float gpuSnapS = snap.GpuLoadPct.HasValue ? snap.GpuLoadPct.Value : -1f;
                    if (gpuSnapS >= 0)            gpuForChartS = gpuSnapS;
                    else if (_cachedGpuPct >= 0)  gpuForChartS = _cachedGpuPct;
                    else                          gpuForChartS = float.NaN;
                    _sparkGpuHistory[gidxS] = gpuForChartS;
                    DrawGpuLoadChart();
                }
                catch (Exception exGpuLoad) { AppLogger.Debug(exGpuLoad.Message); }

                var chartCpuSnap = _chartCpu;
                var chartGpuSnap = _chartGpu;
                var coreFreqsSnap = snap.CoreFreqs.Count > 0 ? snap.CoreFreqs.ToList() : null;
                float cpuFreqMin = _cpuFreqMin, cpuFreqMax = _cpuFreqMax;
                float cpuPowerMin = _cpuPowerMin, cpuPowerMax = _cpuPowerMax;

                var computed = await Task.Run(() =>
                {
                    string cpuAvg = "", gpuAvg = "";
                    if (snap.CpuTemp.HasValue)
                    {
                        float sum = 0; int cnt = 0;
                        foreach (float v in chartCpuSnap) if (!float.IsNaN(v)) { sum += v; cnt++; }
                        if (cnt > 0) cpuAvg = $"{TempUnit.Fmt(sum / cnt)}";
                    }
                    if (snap.GpuTemp.HasValue)
                    {
                        float sum = 0; int cnt = 0;
                        foreach (float v in chartGpuSnap) if (!float.IsNaN(v)) { sum += v; cnt++; }
                        if (cnt > 0) gpuAvg = $"{TempUnit.Fmt(sum / cnt)}";
                    }

                    // CoreFreqList items — formatted off UI thread
                    List<object>? coreItems = null;
                    if (coreFreqsSnap != null && coreFreqsSnap.Count > 0)
                    {
                        float maxFreq = coreFreqsSnap.Max();
                        const double barMaxW = 72.0;
                        coreItems = coreFreqsSnap
                            .Take(16)
                            .Select((f, i) => (object)new
                            {
                                Label    = $"C{i}",
                                FreqText = f >= 1000 ? $"{f/1000f:F1}G" : $"{f:F0}M",
                                BarWidth = maxFreq > 0 ? Math.Max(2.0, barMaxW * f / maxFreq) : 2.0
                            }).ToList();
                    }

                    // String formatting for freq/power min-max — unit in column header, not in cell
                    string cpuFreqMMStr = cpuFreqMin < float.MaxValue
                        ? (cpuFreqMin >= 1000
                            ? $"↓{cpuFreqMin/1000f:F1}  ↑{cpuFreqMax/1000f:F1}"
                            : $"↓{cpuFreqMin:F0}  ↑{cpuFreqMax:F0}")
                        : "";
                    string cpuPowerMMStr = cpuPowerMin < float.MaxValue
                        ? $"↓{cpuPowerMin:F1}  ↑{cpuPowerMax:F1}"
                        : "";

                    return (cpuAvg, gpuAvg, coreItems, cpuFreqMMStr, cpuPowerMMStr);
                });

                // Update Min/Max/Avg labels in chart cards
                if (_cpuMin.HasValue && TxtCpuTempMin != null) TxtCpuTempMin.Text = $"{TempUnit.Fmt(_cpuMin)}";
                if (_cpuMax.HasValue && TxtCpuTempMax != null) TxtCpuTempMax.Text = $"{TempUnit.Fmt(_cpuMax)}";
                // min / max under the dials: only arrows and values, as on the Dashboard (▼ min  ▲ max)
                if (_cpuMin.HasValue && _cpuMax.HasValue) SetArrowRange("TxtStCpuMinMax", TempUnit.Deg(_cpuMin), TempUnit.Deg(_cpuMax));
                if (_gpuMin.HasValue && _gpuMax.HasValue) SetArrowRange("TxtStGpuMinMax", TempUnit.Deg(_gpuMin), TempUnit.Deg(_gpuMax));
                if (computed.cpuAvg.Length > 0 && TxtCpuTempAvg != null) TxtCpuTempAvg.Text = computed.cpuAvg;
                if (_cpuMin.HasValue && FindName("TxtCpuTempMinS") is System.Windows.Controls.TextBlock ctmn) ctmn.Text = $"Min {TempUnit.Deg(_cpuMin)}";
                if (_cpuMax.HasValue && FindName("TxtCpuTempMaxS") is System.Windows.Controls.TextBlock ctmx) ctmx.Text = $"Max {TempUnit.Deg(_cpuMax)}";
                if (computed.cpuAvg.Length > 0 && FindName("TxtCpuTempAvgS") is System.Windows.Controls.TextBlock ctav) ctav.Text = $"Avg {computed.cpuAvg}";
                if (_gpuMin.HasValue && TxtGpuTempMin != null) { TxtGpuTempMin.Text = $"{TempUnit.Fmt(_gpuMin)}"; if (TxtGpuTempMinChart != null) TxtGpuTempMinChart.Text = $"{TempUnit.Deg(_gpuMin)}"; }
                if (_gpuMax.HasValue && TxtGpuTempMax != null) { TxtGpuTempMax.Text = $"{TempUnit.Fmt(_gpuMax)}"; if (TxtGpuTempMaxChart != null) TxtGpuTempMaxChart.Text = $"{TempUnit.Deg(_gpuMax)}"; }
                if (computed.gpuAvg.Length > 0 && TxtGpuTempAvg != null) { TxtGpuTempAvg.Text = computed.gpuAvg; if (TxtGpuTempAvgChart != null) TxtGpuTempAvgChart.Text = computed.gpuAvg; }
                if (_gpuMin.HasValue && FindName("TxtGpuTempMinS") is System.Windows.Controls.TextBlock gtmn) gtmn.Text = $"Min {TempUnit.Deg(_gpuMin)}";
                if (_gpuMax.HasValue && FindName("TxtGpuTempMaxS") is System.Windows.Controls.TextBlock gtmx) gtmx.Text = $"Max {TempUnit.Deg(_gpuMax)}";
                if (computed.gpuAvg.Length > 0 && FindName("TxtGpuTempAvgS") is System.Windows.Controls.TextBlock gtav) gtav.Text = $"Avg {computed.gpuAvg}";

                SMDWin.Services.UiStallLogger.Mark("TempTick:cardCPU");
                // ── CPU detail card ───────────────────────────────────────────
                if (snap.CpuFreqMHz.HasValue && snap.CpuFreqMHz.Value > 0)
                {
                    float freqV = snap.CpuFreqMHz.Value;
                    _cpuFreqMin = Math.Min(_cpuFreqMin, freqV);
                    _cpuFreqMax = Math.Max(_cpuFreqMax, freqV);
                }
                if (snap.CpuPowerW.HasValue && snap.CpuPowerW.Value > 0)
                {
                    float pwrV = snap.CpuPowerW.Value;
                    _cpuPowerMin = Math.Min(_cpuPowerMin, pwrV);
                    _cpuPowerMax = Math.Max(_cpuPowerMax, pwrV);
                    if (FindName("TxtCpuPowerMax") is TextBlock cpMax) cpMax.Text = $"{_cpuPowerMax:F1} W";
                    if (FindName("TxtCpuPowerAvg") is TextBlock cpAvg) cpAvg.Text = $"{(_cpuPowerMin + _cpuPowerMax) / 2f:F1} W";
                }
                float? cpuFreqForLabel = snap.CpuFreqMHz ?? (_lastCpuFreqMHz > 0 ? _lastCpuFreqMHz : (float?)null);
                if (TxtCpuFreq != null && cpuFreqForLabel.HasValue)
                {
                    float fv = cpuFreqForLabel.Value;
                    TxtCpuFreq.Text = $"{fv/1000f:F2} GHz";
                    // a low frequency at idle is normal — not coloured as a problem (slowdown has its own row)
                    TxtCpuFreq.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                }
                else if (TxtCpuFreq != null) TxtCpuFreq.Text = "—";
                    if (snap.CpuFreqMHz.HasValue && snap.CpuFreqMHz.Value > 0)
                    {
                        float fMhz = snap.CpuFreqMHz.Value;
                        _cpuFreqMin = Math.Min(_cpuFreqMin, fMhz);
                        _cpuFreqMax = Math.Max(_cpuFreqMax, fMhz);
                        _cpuFreqSum += fMhz; _cpuFreqCount++;
                        float avg = _cpuFreqSum / _cpuFreqCount;
                        string Fmt(float v) => $"{v / 1000f:F2} GHz";
                        if (FindName("TxtCpuFreqMin") is System.Windows.Controls.TextBlock tfmin)
                            tfmin.Text = Fmt(_cpuFreqMin);
                        if (FindName("TxtCpuFreqMax") is System.Windows.Controls.TextBlock tfmax)
                            tfmax.Text = Fmt(_cpuFreqMax);
                        if (FindName("TxtCpuFreqAvg") is System.Windows.Controls.TextBlock tfavg)
                            tfavg.Text = Fmt(avg);
                    }
                if (TxtCpuFreqMM != null && computed.cpuFreqMMStr.Length > 0) TxtCpuFreqMM.Text = _cpuFreqMin < float.MaxValue ? $"{_cpuFreqMin/1000f:F2}" : "—";
                if (TxtCpuPower != null)
                    TxtCpuPower.Text = snap.CpuPowerW.HasValue ? $"{snap.CpuPowerW.Value:F1} W" : "—";
                if (FindName("RowCpuPower") is System.Windows.FrameworkElement rCpuPwr)
                    rCpuPwr.Visibility = snap.CpuPowerW.HasValue ? Visibility.Visible : Visibility.Collapsed;
                if (TxtVCore != null)
                    TxtVCore.Text = snap.CpuVCoreV.HasValue ? $"{snap.CpuVCoreV.Value:F3}" : "—";  // unit in header (V)
                if (FindName("RowCpuVCore") is System.Windows.FrameworkElement rVCore)
                    rVCore.Visibility = snap.CpuVCoreV.HasValue ? Visibility.Visible : Visibility.Collapsed;
                if (TxtCpuPowerMM != null && computed.cpuPowerMMStr.Length > 0) TxtCpuPowerMM.Text = _cpuPowerMin < float.MaxValue ? $"{_cpuPowerMin:F1} W" : "—";

                if (FindName("TxtCpuCoresPower") is TextBlock cpCores && snap.CpuCoresPowerW.HasValue)
                {
                    cpCores.Text = $"{snap.CpuCoresPowerW.Value:F1} W";
                }
                if (FindName("TxtCpuUncorePower") is TextBlock cpUncore && snap.CpuUncorePowerW.HasValue)
                {
                    cpUncore.Text = $"{snap.CpuUncorePowerW.Value:F1} W";
                }

                if (snap.CoreTemps.Count > 0)
                {
                    if (FindName("RowCpuCoreTemps") is System.Windows.FrameworkElement rCoreTemps)
                        rCoreTemps.Visibility = Visibility.Visible;
                    float coreMax = snap.CoreTemps.Max();
                    float coreMin = snap.CoreTemps.Min();
                    float coreAvgNow = snap.CoreTemps.Average();

                    // Session aggregates: lowest of all cores ever, highest of all cores ever, running avg
                    if (coreMin < _coreTempsSessMin) _coreTempsSessMin = coreMin;
                    if (coreMax > _coreTempsSessMax) _coreTempsSessMax = coreMax;
                    _coreTempsSessSum += coreAvgNow; _coreTempsSessCnt++;

                    if (FindName("TxtCoreTempsNow") is TextBlock tCoreNow)
                    {
                        tCoreNow.Text = $"{TempUnit.Convert(coreMin):F0}–{TempUnit.Fmt(coreMax)}";
                        tCoreNow.Foreground = coreMax > 85 ? _brRed : coreMax > 70 ? _brOrange : _brGreen;
                    }
                    if (FindName("TxtCoreTempsMin") is TextBlock tCoreMin)
                        tCoreMin.Text = $"{TempUnit.Fmt(_coreTempsSessMin)}";
                    if (FindName("TxtCoreTempsMax") is TextBlock tCoreMax)
                    {
                        tCoreMax.Text = $"{TempUnit.Fmt(_coreTempsSessMax)}";
                        tCoreMax.Foreground = _coreTempsSessMax > 85 ? _brRed : _coreTempsSessMax > 70 ? _brOrange : _brGreen;
                    }
                    if (FindName("TxtCoreTempsAvg") is TextBlock tCoreAvg && _coreTempsSessCnt > 0)
                        tCoreAvg.Text = $"{TempUnit.Fmt(_coreTempsSessSum / _coreTempsSessCnt)}";
                    if (FindName("TxtCoreTempsSubtitle") is TextBlock tCoreSub)
                        tCoreSub.Text = PT(snap.CoreTemps.Count == 1 ? "{0} core" : "{0} cores", snap.CoreTemps.Count);
                    // Regenerate the expand rows if the number of cores changed
                    if (FindName("CoreTempsExpandPanel") is System.Windows.Controls.StackPanel corePanel
                        && corePanel.Children.Count != snap.CoreTemps.Count
                        && corePanel.Visibility == Visibility.Visible)
                    {
                        UpdateCoreTempsPanel(corePanel, snap);
                    }
                    else if (FindName("CoreTempsExpandPanel") is System.Windows.Controls.StackPanel corePanelUpd
                             && corePanelUpd.Visibility == Visibility.Visible)
                    {
                        UpdateCoreTempsPanel(corePanelUpd, snap);
                    }
                }

                if (snap.VrmTemp.HasValue)
                {
                    if (FindName("TxtVrmTempNow") is TextBlock tVrm) tVrm.Text = $"{TempUnit.Fmt(snap.VrmTemp.Value)}";
                    if (FindName("RowVrmTemp") is System.Windows.FrameworkElement rVrm) rVrm.Visibility = Visibility.Visible;
                }
                if (snap.ChipsetTemp.HasValue)
                {
                    if (FindName("TxtChipsetTempNow") is TextBlock tChip) tChip.Text = $"{TempUnit.Fmt(snap.ChipsetTemp.Value)}";
                    if (FindName("RowChipsetTemp") is System.Windows.FrameworkElement rChip) rChip.Visibility = Visibility.Visible;
                }

                if (snap.GpuHotSpot.HasValue)
                {
                    if (FindName("TxtGpuHotSpotNow") is TextBlock tHot) tHot.Text = $"{TempUnit.Fmt(snap.GpuHotSpot.Value)}";
                    if (FindName("RowGpuHotSpot") is System.Windows.FrameworkElement rHot) rHot.Visibility = Visibility.Visible;
                }
                if (snap.GpuVramTemp.HasValue)
                {
                    if (FindName("TxtGpuVramTempNow") is TextBlock tVram) tVram.Text = $"{TempUnit.Fmt(snap.GpuVramTemp.Value)}";
                    if (FindName("RowGpuVramTemp") is System.Windows.FrameworkElement rVram) rVram.Visibility = Visibility.Visible;
                }
                if (snap.BatteryLiveW.HasValue)
                {
                    if (FindName("TxtBatLiveW") is TextBlock tBatLive)
                        tBatLive.Text = snap.BatteryLiveVoltage.HasValue
                            ? $"{snap.BatteryLiveW.Value:F1} W  ·  {snap.BatteryLiveVoltage.Value:F2} V"
                            : $"{snap.BatteryLiveW.Value:F1} W";
                    if (FindName("RowBatteryLive") is System.Windows.FrameworkElement rBatLive) rBatLive.Visibility = Visibility.Visible;
                }
                PushBatterySparkline(snap.BatteryLiveW);
                if (snap.NvmeTemp.HasValue)
                {
                    if (FindName("TxtNvmeTempNow") is TextBlock tNvme) tNvme.Text = $"{TempUnit.Fmt(snap.NvmeTemp.Value)}";
                    if (FindName("RowNvmeTemp") is System.Windows.FrameworkElement rNvme) rNvme.Visibility = Visibility.Visible;
                }

                // Processes / Threads / Handles
                if (FindName("TxtCpuProcesses") is System.Windows.Controls.TextBlock tproc && _cachedProcessCount > 0)
                    tproc.Text = _cachedProcessCount.ToString("N0");
                if (FindName("TxtCpuThreads") is System.Windows.Controls.TextBlock tthrd && _cachedThreadCount > 0)
                    tthrd.Text = _cachedThreadCount.ToString("N0");
                if (FindName("TxtCpuHandles") is System.Windows.Controls.TextBlock thand && _cachedHandleCount > 0)
                    thand.Text = _cachedHandleCount.ToString("N0");
                if (TxtCpuLoad != null)
                {
                    float? liveCpuPct = CpuLoadNow;
                    TxtCpuLoad.Text = liveCpuPct.HasValue ? $"{liveCpuPct.Value:F0}%" : "—";
                }
                if (TxtCpuUsageLive != null)
                {
                    float? liveCpuPct2 = CpuLoadNow;
                    TxtCpuUsageLive.Text = liveCpuPct2.HasValue ? $"{liveCpuPct2.Value:F0}%" : "--%";
                }

                // Per-core frequency bars — list already built on background thread
                if (CoreFreqList != null && computed.coreItems != null)
                    CoreFreqList.ItemsSource = computed.coreItems;

                SMDWin.Services.UiStallLogger.Mark("TempTick:cardGPU");
                // ── GPU detail card ───────────────────────────────────────────
                if (snap.GpuFreqMHz.HasValue && snap.GpuFreqMHz.Value > 0)
                {
                    float gFreqV = snap.GpuFreqMHz.Value;
                    _gpuFreqMin = Math.Min(_gpuFreqMin, gFreqV);
                    _gpuFreqMax = Math.Max(_gpuFreqMax, gFreqV);
                    string FmtGF(float v) => $"{v/1000f:F2} GHz";
                    if (FindName("TxtGpuClockMax") is TextBlock gcMax) gcMax.Text = FmtGF(_gpuFreqMax);
                    if (FindName("TxtGpuClockAvg") is TextBlock gcAvg) gcAvg.Text = FmtGF((_gpuFreqMin + _gpuFreqMax) / 2f);
                }
                if (snap.GpuPowerW.HasValue && snap.GpuPowerW.Value > 0)
                {
                    float gPwrV = snap.GpuPowerW.Value;
                    _gpuPowerMin = Math.Min(_gpuPowerMin, gPwrV);
                    _gpuPowerMax = Math.Max(_gpuPowerMax, gPwrV);
                }
                if (snap.GpuMemUsedMB.HasValue && snap.GpuMemUsedMB.Value > 0)
                {
                    float gVram = snap.GpuMemUsedMB.Value;
                    if (!_gpuVramMin.HasValue || gVram < _gpuVramMin.Value) _gpuVramMin = gVram;
                    if (!_gpuVramMax.HasValue || gVram > _gpuVramMax.Value) _gpuVramMax = gVram;
                    if (FindName("TxtGpuVramUsed") is TextBlock gvNow) gvNow.Text = $"{gVram:F0} MB";
                    if (FindName("TxtGpuVramMin") is TextBlock gvMin) gvMin.Text = $"{_gpuVramMin:F0} MB";
                    if (FindName("TxtGpuVramMax") is TextBlock gvMax) gvMax.Text = $"{_gpuVramMax:F0} MB";
                    if (FindName("TxtGpuVramAvg") is TextBlock gvAvg) gvAvg.Text = $"{((_gpuVramMin ?? 0) + (_gpuVramMax ?? 0)) / 2f:F0} MB";
                }
                if (TxtGpuFreq != null)
                    TxtGpuFreq.Text = snap.GpuFreqMHz.HasValue
                        ? $"{snap.GpuFreqMHz.Value/1000f:F2} GHz"
                        : "—";
                    if (FindName("TxtGpuFreqKpi") is System.Windows.Controls.TextBlock tgfk && snap.GpuFreqMHz.HasValue)
                        tgfk.Text = $"{snap.GpuFreqMHz.Value:F0} MHz";
                if (TxtGpuFreqMM != null && _gpuFreqMin < float.MaxValue)
                    TxtGpuFreqMM.Text = $"{_gpuFreqMin/1000f:F2} GHz";
                if (FindName("TxtGpuMemClockVal") is System.Windows.Controls.TextBlock tgmf)
                    tgmf.Text = snap.GpuMemFreqMHz.HasValue ? $"{snap.GpuMemFreqMHz.Value:F0}" : "—";  // unit in label (MHz)
                if (FindName("RowGpuMemClock") is System.Windows.FrameworkElement rGpuMem)
                    rGpuMem.Visibility = snap.GpuMemFreqMHz.HasValue ? Visibility.Visible : Visibility.Collapsed;
                if (TxtGpuPower != null)
                    TxtGpuPower.Text = snap.GpuPowerW.HasValue ? $"{snap.GpuPowerW.Value:F1}" : "—";  // unit in header (W)
                if (TxtGpuPowerMM != null && _gpuPowerMin < float.MaxValue)
                    TxtGpuPowerMM.Text = $"↓{_gpuPowerMin:F1}  ↑{_gpuPowerMax:F1} W";
                if (TxtGpuLoad != null)
                    TxtGpuLoad.Text = GpuLoadNow is float tgl ? $"{tgl:F0}" : "—";  // unit in header (%)

                if (snap.CpuVCoreV.HasValue && snap.CpuVCoreV.Value > 0)
                {
                    float vc = snap.CpuVCoreV.Value;
                    _cpuVCoreMin = Math.Min(_cpuVCoreMin, vc);
                    _cpuVCoreMax = Math.Max(_cpuVCoreMax, vc);
                    _cpuVCoreSum += vc; _cpuVCoreCnt++;
                    if (FindName("TxtCpuVCoreVal") is TextBlock vcV) vcV.Text = $"{vc:F3} V";
                    if (FindName("TxtCpuVCoreMin") is TextBlock vcMn) vcMn.Text = $"{_cpuVCoreMin:F3} V";
                    if (FindName("TxtCpuVCoreMax") is TextBlock vcMx) { vcMx.Text = $"{_cpuVCoreMax:F3} V"; vcMx.Foreground = _cpuVCoreMax > 1.40f ? _brRed : _cpuVCoreMax > 1.30f ? _brOrange : _brGreen; }
                    if (FindName("TxtCpuVCoreAvg") is TextBlock vcAv && _cpuVCoreCnt > 0) vcAv.Text = $"{_cpuVCoreSum/_cpuVCoreCnt:F3} V";
                }

                if (snap.GpuMemFreqMHz.HasValue && snap.GpuMemFreqMHz.Value > 0)
                {
                    float gmf = snap.GpuMemFreqMHz.Value;
                    _gpuMemFreqMin = Math.Min(_gpuMemFreqMin, gmf);
                    _gpuMemFreqMax = Math.Max(_gpuMemFreqMax, gmf);
                    string FmtMF(float v) => $"{v:F0} MHz";
                    if (FindName("TxtGpuMemClockVal") is TextBlock gmV) gmV.Text = FmtMF(gmf);
                    if (FindName("TxtGpuMemClockMin") is TextBlock gmMn) gmMn.Text = FmtMF(_gpuMemFreqMin);
                    if (FindName("TxtGpuMemClockMax") is TextBlock gmMx) gmMx.Text = FmtMF(_gpuMemFreqMax);
                    if (FindName("TxtGpuMemClockAvg") is TextBlock gmAv) gmAv.Text = FmtMF((_gpuMemFreqMin + _gpuMemFreqMax) / 2f);
                }

                {
                    const float basePowerW = 45f; // motherboard + RAM + SSD baseline
                    float cpuW = snap.CpuPowerW ?? 0f;
                    float gpuW = snap.GpuPowerW ?? 0f;
                    if (cpuW > 0 || gpuW > 0)
                    {
                        float totalW = cpuW + gpuW + basePowerW;
                        _sysPowerMin = Math.Min(_sysPowerMin, totalW);
                        if (!_sysPowerPeak.HasValue || totalW > _sysPowerPeak.Value)
                            _sysPowerPeak = totalW;
                        float avgW = (_sysPowerMin + _sysPowerPeak.Value) / 2f;
                        if (FindName("TxtGpuPowerVal")  is TextBlock spV)  spV.Text  = $"{totalW:F0} W";
                        if (FindName("TxtGpuPowerMin2") is TextBlock spMn) spMn.Text = $"{_sysPowerMin:F0} W";
                        if (FindName("TxtGpuPowerMax2") is TextBlock spMx) spMx.Text = $"{_sysPowerPeak.Value:F0} W";
                        if (FindName("TxtGpuPowerAvg2") is TextBlock spAv) spAv.Text = $"{avgW:F0} W";
                        if (FindName("RowGpuPower") is System.Windows.FrameworkElement rSysPwr)
                            rSysPwr.Visibility = Visibility.Visible;
                    }
                }

                if (snap.FanSpeeds?.Count > 0 && FindName("FanRowsContainer") is System.Windows.Controls.StackPanel fanContainer)
                {

                    // Rebuild the rows only if the fans changed
                    var fanNames = snap.FanSpeeds.Select(f => f.Name).ToList();
                    bool fansChanged = !fanNames.SequenceEqual(_lastFanNames);
                    if (fansChanged)
                    {
                        fanContainer.Children.Clear();
                        _lastFanNames.Clear();
                        _lastFanNames.AddRange(fanNames);
                        foreach (var (name, _) in snap.FanSpeeds)
                        {
                            string sanitized = name.Replace(" ", "_").Replace("#", "").Replace("—", "_");
                            string tag = $"Fan_{sanitized}";

                            // Buffer + chart def — only once per fan, on first detection (persists between row rebuilds, unlike the UI).
                            if (!_fanChartBuffers.ContainsKey(tag))
                            {
                                var buf = new float[ChartMaxPoints];
                                Array.Fill(buf, float.NaN);
                                _fanChartBuffers[tag] = buf;
                                var fanColor = (TryFindResource("ChartGreenColor") as WpfColor?) ?? WpfColor.FromRgb(34,197,94);
                                _chartDefs[tag] = new($"{name} (RPM)", fanColor,
                                    c => DrawSingleTempChart(c, _fanChartBuffers[tag], ResolveChartColor(fanColor), 0f, 0f, "RPM", "F0"),
                                    0f, 0f, "RPM", "F0");
                            }

                            var rowGrid = new System.Windows.Controls.Grid { Margin = new Thickness(8, 1, 8, 1), MinHeight = 28, Cursor = System.Windows.Input.Cursors.Hand, Tag = tag };
                            rowGrid.MouseLeftButtonUp += SensorRow_Click;
                            var rowHoverStyle = new Style(typeof(System.Windows.Controls.Grid));
                            rowHoverStyle.Setters.Add(new Setter(System.Windows.Controls.Grid.BackgroundProperty, System.Windows.Media.Brushes.Transparent));
                            var hoverTrigger = new Trigger { Property = System.Windows.Controls.Grid.IsMouseOverProperty, Value = true };
                            hoverTrigger.Setters.Add(new Setter(System.Windows.Controls.Grid.BackgroundProperty, FindResource("AccentLightBrush")));
                            rowHoverStyle.Triggers.Add(hoverTrigger);
                            rowGrid.Style = rowHoverStyle;
                            rowGrid.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new GridLength(0) });
                            rowGrid.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new GridLength(1, GridUnitType.Star), MinWidth = 120 });
                            rowGrid.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new GridLength(70) });
                            rowGrid.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new GridLength(62) });
                            rowGrid.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new GridLength(62) });
                            rowGrid.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new GridLength(0) });

                            // Checkbox — registered with RegisterName, so FindName (used by UpdateCheckbox) can find it like the static sensors.
                            string chkName = $"ChkFan_{sanitized}";
                            var chk = new Border
                            {
                                Name = chkName, Width = 14, Height = 14, CornerRadius = new CornerRadius(3),
                                Background = System.Windows.Media.Brushes.Transparent, BorderThickness = new Thickness(1.5),
                                VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                            };
                            chk.SetResourceReference(Border.BorderBrushProperty, "CardBorderBrush");
                            try { UnregisterName(chkName); } catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); /* was not registered yet */ }
                            RegisterName(chkName, chk);
                            _tagToChk[tag] = chkName;
                            System.Windows.Controls.Grid.SetColumn(chk, 0); rowGrid.Children.Add(chk);

                            // Fan label — a StackPanel with a coloured bar, like any other row in the table (see "Power" above in XAML).
                            var lblPanel = new System.Windows.Controls.StackPanel { Orientation = System.Windows.Controls.Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(4, 0, 0, 0) };
                            lblPanel.Children.Add(new System.Windows.Controls.TextBlock
                            {
                                Text = name, FontSize = Ui.FontM, FontWeight = FontWeights.SemiBold,
                                Foreground = (System.Windows.Media.Brush)FindResource("TextPrimaryBrush"),
                                VerticalAlignment = VerticalAlignment.Center
                            });
                            System.Windows.Controls.Grid.SetColumn(lblPanel, 1); rowGrid.Children.Add(lblPanel);

                            // Now / Min / Max / Avg — the same style as the rest of the sensors
                            var valTb = new System.Windows.Controls.TextBlock
                            {
                                Name = $"TxtFan_{sanitized}_Val",
                                Text = "—", FontSize = Ui.FontL, FontWeight = FontWeights.Bold,
                                Foreground = (System.Windows.Media.Brush)FindResource("AccentBrush"),
                                TextAlignment = TextAlignment.Right, VerticalAlignment = VerticalAlignment.Center
                            };
                            System.Windows.Controls.Grid.SetColumn(valTb, 2); rowGrid.Children.Add(valTb);

                            var minTb = new System.Windows.Controls.TextBlock
                            {
                                Name = $"TxtFan_{sanitized}_Min", Text = "—", FontSize = Ui.FontL,
                                Foreground = (System.Windows.Media.Brush)FindResource("TextSecondaryBrush"),
                                TextAlignment = TextAlignment.Right, VerticalAlignment = VerticalAlignment.Center
                            };
                            System.Windows.Controls.Grid.SetColumn(minTb, 3); rowGrid.Children.Add(minTb);

                            var maxTb = new System.Windows.Controls.TextBlock
                            {
                                Name = $"TxtFan_{sanitized}_Max", Text = "—", FontSize = Ui.FontL,
                                Foreground = (System.Windows.Media.Brush)FindResource("StatusWarnBrush"),
                                TextAlignment = TextAlignment.Right, VerticalAlignment = VerticalAlignment.Center
                            };
                            System.Windows.Controls.Grid.SetColumn(maxTb, 4); rowGrid.Children.Add(maxTb);

                            var avgTb = new System.Windows.Controls.TextBlock
                            {
                                Name = $"TxtFan_{sanitized}_Avg", Text = "—", FontSize = Ui.FontL,
                                Foreground = (System.Windows.Media.Brush)FindResource("TextSecondaryBrush"),
                                TextAlignment = TextAlignment.Right, VerticalAlignment = VerticalAlignment.Center
                            };
                            System.Windows.Controls.Grid.SetColumn(avgTb, 5); rowGrid.Children.Add(avgTb);

                            _fanRowRefs[tag] = (valTb, minTb, maxTb, avgTb);
                            fanContainer.Children.Add(rowGrid);
                        }
                    }

                    // Update the values (Now/Min/Max/Avg) + push into the chart buffer — on EVERY tick, whether or not the rows were rebuilt.
                    for (int fi = 0; fi < snap.FanSpeeds.Count && fi < fanContainer.Children.Count; fi++)
                    {
                        if (fanContainer.Children[fi] is not System.Windows.Controls.Grid fg || fg.Tag is not string tag) continue;
                        float rpm = snap.FanSpeeds[fi].Rpm;
                        if (!_fanRowRefs.TryGetValue(tag, out var refs)) continue;

                        refs.val.Text = $"{rpm:F0} RPM";
                        refs.val.Foreground = rpm > 0 ? _brGreen : _brGray;

                        {
                            var mm = _fanMinMax.TryGetValue(tag, out var existing)
                                ? (Math.Min(existing.min, rpm), Math.Max(existing.max, rpm), existing.sum + rpm, existing.count + 1)
                                : (rpm, rpm, (double)rpm, 1L);
                            _fanMinMax[tag] = mm;

                            refs.min.Text = $"{mm.Item1:F0}";
                            refs.max.Text = $"{mm.Item2:F0}";
                            refs.avg.Text = $"{mm.Item3 / mm.Item4:F0}";
                        }

                        // Push into the chart buffer (the same idx position as the rest of the sensors — see the
                        // "for (int s = 0; s < stepsFull...)" loop below, which increments _chartIdx; here we write ONLY at the current
                        // position, once per tick, like _sparkGpuHistory[idx] below).
                        if (_fanChartBuffers.TryGetValue(tag, out var fbuf))
                        {
                            int fidx = _chartIdx % ChartMaxPoints;
                            fbuf[fidx] = rpm > 0 ? rpm : float.NaN;
                        }
                    }
                }
                else
                {
                    if (FindName("FanRowsContainer") is System.Windows.Controls.StackPanel fanContainerHide && fanContainerHide.Children.Count > 0)
                    {
                        fanContainerHide.Children.Clear();
                        _lastFanNames.Clear();
                    }
                }

                // Encode / Decode utilization
                if (FindName("TxtGpuEncode") is System.Windows.Controls.TextBlock tge)
                    tge.Text = _cachedGpuEncodePct >= 0 ? $"{_cachedGpuEncodePct:F0}%" : "—";
                if (FindName("TxtGpuDecode") is System.Windows.Controls.TextBlock tgd)
                    tgd.Text = _cachedGpuDecodePct >= 0 ? $"{_cachedGpuDecodePct:F0}%" : "—";
                if (TxtGpuFanLive != null)
                    TxtGpuFanLive.Text = snap.GpuLoadPct.HasValue ? $"{snap.GpuLoadPct.Value:F0} %" : "— %";
                if (TxtGpuVramChart != null)
                    TxtGpuVramChart.Text = snap.GpuMemUsedMB.HasValue ? $"{snap.GpuMemUsedMB.Value:F0} MB" : "—";


                bool lhmThrottled = snap.CpuThrottled || snap.GpuThrottled;
                string lhmReason  = snap.ThrottleReason;

                float kernelFreqMHz = snap.CpuFreqMHz ?? 0f;
                if (_cpuStress.Running)
                {
                    _totalTempSamples++;
                    // the Windows clock counter is used only while it moves: when the detector found it stuck on one value
                    // (some laptops without the sensor driver), it would show a frozen clock
                    if (_lastThrottle?.HasFrequency != false)
                        await Task.Run(() => { kernelFreqMHz = ReadKernelFreqMHz(); });
                    if (lhmThrottled) _throttleSamples++;
                    _lastCpuFreqMHz = _lastThrottle?.HasFrequency != false ? kernelFreqMHz : 0f;
                }
                else
                {
                    // the clock read during a stress test is not shown after it: without a live source the value stays "—"
                    _lastCpuFreqMHz = 0f;
                }

                // ThrottleDetector: read the last value (updated async)
                var _tSnap = _lastThrottle;
                bool detectorThrottled = _tSnap?.IsThrottled == true;
                bool isBenignPowerLimit = _tSnap?.Reason == SMDWin.Services.ThrottleReason.PowerLimit;
                (SolidColorBrush color, string tier) ClassifyThrottleTier(SMDWin.Services.ThrottleSnapshot? snap)
                {
                    if (snap == null || snap.Reason == SMDWin.Services.ThrottleReason.None)
                        return (_brGreen, "none");
                    return snap.Reason switch
                    {
                        SMDWin.Services.ThrottleReason.PowerLimit => (_brCoolBlue, "info"),
                        SMDWin.Services.ThrottleReason.Thermal    => (_brRed, "critical"),
                        SMDWin.Services.ThrottleReason.BdProchot  => (_brRed, "critical"),
                        _ => (_brOrange, "warning"), // BatterySaver, Unknown, FixedFrequency
                    };
                }
                bool showThrottle = lhmThrottled || detectorThrottled ||
                                    (_cpuStress.Running && _throttleSamples > 0);

                bool isBdProchot2 = _tSnap?.Reason == SMDWin.Services.ThrottleReason.BdProchot;
                if (FindName("BdprochotBadge") is Border bdBadge)
                    bdBadge.Visibility = isBdProchot2 ? Visibility.Visible : Visibility.Collapsed;
                if (FindName("TxtStressThrottleLabel") is System.Windows.Controls.TextBlock thl2)
                {
                    bool isBdProchot = _tSnap?.Reason == SMDWin.Services.ThrottleReason.BdProchot;
                    if (!showThrottle)
                    {
                        // turbo disabled in the power plan is not throttling, but it explains the low frequency
                        bool turboOff = _tSnap?.BoostDisabled == true;
                        thl2.Text = turboOff
                            ? "No throttle · " + SMDWin.Services.LanguageService.S("Throttle", "TurboOffLabel", "Turbo off")
                            : "No throttle";
                        thl2.Foreground = _brGreen;
                        if (FindName("ThrottleDot") is System.Windows.Shapes.Ellipse dot2) dot2.Fill = _brGreen;
                        if (FindName("TxtThrottleInfo") is System.Windows.Controls.TextBlock ti2)
                            ti2.Text = turboOff ? SMDWin.Services.LanguageService.S("Throttle", "TurboOffInfo",
                                "Turbo is turned off in the Windows power plan (Power page → Processor Boost Mode)") : "";
                    }
                    else if (isBdProchot)
                    {
                        thl2.Text = "BD PROCHOT";
                        thl2.Foreground = _brRed;
                        if (FindName("ThrottleDot") is System.Windows.Shapes.Ellipse dot2) dot2.Fill = _brRed;
                        if (FindName("TxtThrottleInfo") is System.Windows.Controls.TextBlock ti2)
                            ti2.Text = _tSnap?.FreqMHz > 0
                                ? $"Locked at {_tSnap!.FreqMHz:F0} MHz — use ThrottleStop to disable BD PROCHOT"
                                : "Power/charging issue detected — see ThrottleStop";
                    }
                    else if (isBenignPowerLimit)
                    {
                        thl2.Text = "Power Limit (normal)";
                        thl2.Foreground = _brCoolBlue;
                        if (FindName("ThrottleDot") is System.Windows.Shapes.Ellipse dot2) dot2.Fill = _brCoolBlue;
                        if (FindName("TxtThrottleInfo") is System.Windows.Controls.TextBlock ti2)
                            ti2.Text = _tSnap?.FreqMHz > 0
                                ? $"@ {_tSnap!.FreqMHz:F0} MHz — expected under sustained load, not an issue"
                                : "Expected under sustained load, not an issue";
                    }
                    else if (_tSnap?.Reason == SMDWin.Services.ThrottleReason.Thermal)
                    {
                        thl2.Text = _tSnap.ReasonLabel;
                        thl2.Foreground = _brRed;
                        if (FindName("ThrottleDot") is System.Windows.Shapes.Ellipse dot2) dot2.Fill = _brRed;
                        if (FindName("TxtThrottleInfo") is System.Windows.Controls.TextBlock ti2)
                            ti2.Text = _tSnap?.FreqMHz > 0 ? $"@ {_tSnap!.FreqMHz:F0} MHz — {TempUnit.Fmt(_tSnap.CpuTempC)}" : "";
                    }
                    else
                    {
                        string reason = (_tSnap?.Reason != SMDWin.Services.ThrottleReason.None && !string.IsNullOrEmpty(_tSnap?.ReasonLabel))
                            ? _tSnap!.ReasonLabel
                            : (!string.IsNullOrEmpty(lhmReason) ? lhmReason : "Frequency limited");
                        thl2.Text = reason;
                        thl2.Foreground = _brOrange;
                        if (FindName("ThrottleDot") is System.Windows.Shapes.Ellipse dot2) dot2.Fill = _brOrange;
                        if (FindName("TxtThrottleInfo") is System.Windows.Controls.TextBlock ti2)
                            ti2.Text = _tSnap?.FreqMHz > 0 ? $"@ {_tSnap!.FreqMHz:F0} MHz" : "";
                    }
                }

                if (showThrottle && ThrottleBanner != null)
                {
                    if (ThrottleBanner != null) ThrottleBanner.Visibility = Visibility.Visible;
                    if (TxtThrottleInfo != null)
                    {
                        string reason;
                        if (_tSnap?.IsSevere == true && _tSnap.Reason != SMDWin.Services.ThrottleReason.None)
                        {
                            reason = _tSnap.ReasonLabel;
                            if (TxtThrottleInfo.ToolTip == null && !string.IsNullOrEmpty(_tSnap.ReasonDetail))
                                if (TxtThrottleInfo != null) TxtThrottleInfo.ToolTip = _tSnap.ReasonDetail;
                        }
                        else
                            reason = !string.IsNullOrEmpty(lhmReason) ? lhmReason : "Frequency limited";

                        float showFreq = (_tSnap?.FreqMHz ?? 0) > 0 ? _tSnap!.FreqMHz : kernelFreqMHz;
                        string freqPart = showFreq > 0 ? $" @ {showFreq:F0} MHz" : "";
                        string pctPart  = _tSnap != null ? $" ({_tSnap.FreqRatio * 100:F0}% din max)" : "";
                        string icon = (isBenignPowerLimit && _tSnap?.IsSevere != true) ? "ℹ" : "⚠";
                        if (TxtThrottleInfo != null) TxtThrottleInfo.Text = $"{icon} {reason}{freqPart}{pctPart}";
                    }
                }
                else if (ThrottleBanner != null && !lhmThrottled && !detectorThrottled)
                {
                    if (ThrottleBanner != null) ThrottleBanner.Visibility = Visibility.Collapsed;
                }

                // Update throttle LED indicator on CPU Freq card
                try
                {
                    if (ThrottleLed != null)
                    {
                        var _tl = _lastThrottle;
                        var (tlColor, tlTier) = ClassifyThrottleTier(_tl);
                        if (ThrottleLed != null) ThrottleLed.Fill = showThrottle ? tlColor : _brGreen;
                        if (TxtThrottleLedLabel != null)
                        {
                            if (TxtThrottleLedLabel != null) TxtThrottleLedLabel.Text = !showThrottle ? "No throttle"
                                : tlTier switch
                                {
                                    "critical" => $"⚠ {_tl!.ReasonLabel}",
                                    "info"     => "Power Limit (normal)",
                                    _          => "Throttling",
                                };
                        }
                    }
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }

                float _ct5 = snap.CpuTemp ?? float.NaN;
                if (!float.IsNaN(_ct5) && _ct5 > 0) { _lastGoodCpuTemp = _ct5; _cpuTempMissTicks = 0; }
                else if (_lastGoodCpuTemp > 0 && ++_cpuTempMissTicks <= 5) _ct5 = _lastGoodCpuTemp;
                float _gt5 = snap.GpuTemp ?? float.NaN;
                if (!float.IsNaN(_gt5) && _gt5 > 0) { _lastGoodGpuTemp = _gt5; _gpuTempMissTicks = 0; }
                else if (_lastGoodGpuTemp > 0 && ++_gpuTempMissTicks <= 5) _gt5 = _lastGoodGpuTemp;
                float vCpuFreqFull;
                if (_cpuStress.Running && _lastCpuFreqMHz > 0)
                    vCpuFreqFull = _lastCpuFreqMHz;      // kernel freq, always fresh
                else if (snap.CpuFreqMHz.HasValue && snap.CpuFreqMHz.Value > 0)
                    vCpuFreqFull = snap.CpuFreqMHz.Value; // LHM when not stressing
                else if (_lastCpuFreqMHz > 0)
                    vCpuFreqFull = _lastCpuFreqMHz;       // fallback kernel
                else
                    vCpuFreqFull = float.NaN;
                float vCpuUsageFull = _cachedCpuPct >= 0 ? _cachedCpuPct : float.NaN;
                if (snap.CpuLoadPct.HasValue && _cachedCpuPct >= 0
                    && Math.Abs(snap.CpuLoadPct.Value - _cachedCpuPct) > 15f)
                {
                    _loadDivCount++; _loadDivSumPc += _cachedCpuPct; _loadDivSumLhm += snap.CpuLoadPct.Value;
                    _loadDivMaxAbs = Math.Max(_loadDivMaxAbs, Math.Abs(snap.CpuLoadPct.Value - _cachedCpuPct));
                }
                if (_loadDivCount > 0 && (DateTime.UtcNow - _loadDivLastLogUtc).TotalMinutes >= 5)
                {
                    AppLogger.Debug("S3-DIAG CpuLoad: {N} ticks with a difference > 15pp in the last 5 min - shown counter (Processor Utility) average {Pc:F0}%, LHM average {Lhm:F0}%, max difference {Max:F0}pp",
                        _loadDivCount, _loadDivSumPc / _loadDivCount, _loadDivSumLhm / _loadDivCount, _loadDivMaxAbs);
                    _loadDivCount = 0; _loadDivSumPc = 0; _loadDivSumLhm = 0; _loadDivMaxAbs = 0;
                    _loadDivLastLogUtc = DateTime.UtcNow;
                }
                // RAM % — stored in a same-size buffer to match the time interval
                float vRamUsageFull = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                    ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f) : float.NaN;
                float vCpuPowerFull = snap.CpuPowerW   ?? float.NaN;
                float vGpuLoadFull  = GpuLoadNow ?? float.NaN;
                float vGpuFreqFull  = snap.GpuFreqMHz  ?? float.NaN;
                float vGpuVramFull  = snap.GpuMemUsedMB ?? float.NaN;
                float vGpuPowerFull = snap.GpuPowerW   ?? float.NaN;
                float vCpuVCoreFull   = snap.CpuVCoreV    ?? float.NaN;
                float vGpuMemFreqFull = snap.GpuMemFreqMHz ?? float.NaN;
                float vSysPowerFull = ComputeSystemPowerW(snap.CpuPowerW, snap.GpuPowerW,
                    snap.BatteryLiveW, _summary?.HasBattery == true);

                int stepsFull = ComputeChartCatchUpSteps();
                PushChartSample(stepsFull, new[]
                {
                    _ct5, _gt5, vCpuFreqFull, vCpuUsageFull, vRamUsageFull, vCpuPowerFull, vGpuLoadFull, vGpuFreqFull,
                    vGpuVramFull, vGpuPowerFull, vCpuVCoreFull, vGpuMemFreqFull, vSysPowerFull, CurrentDiskTempForChart(), vGpuLoadFull,
                }, gap: windowHidden && bgRec == BgRecMode.Off);
                PushSlotHistory(new[]
                {
                    _ct5, _gt5, vCpuFreqFull, vCpuUsageFull, vRamUsageFull, vCpuPowerFull, vGpuLoadFull, vGpuFreqFull,
                    vGpuVramFull, vCpuVCoreFull, vGpuMemFreqFull, vSysPowerFull, CurrentDiskTempForChart(),
                }, gap: windowHidden && bgRec == BgRecMode.Off);
                int idxLastFull = (_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints;
                _tempDataFresh = true;
                if (PanelStress?.Visibility == Visibility.Visible)
                {
                    DrawTempChart();

                    var slotCanvases = new[] {
                        FindName("CpuTempCanvas")  as System.Windows.Controls.Canvas ?? CpuTempChart,
                        FindName("CpuFreqCanvas")  as System.Windows.Controls.Canvas ?? CpuFreqChart,
                        FindName("CpuUsageCanvas") as System.Windows.Controls.Canvas ?? CpuUsageChart,
                        FindName("GpuTempCanvas")  as System.Windows.Controls.Canvas ?? GpuTempChart
                    };
                    var slotValNames = new[] { "TxtChartVal1", "TxtChartVal2", "TxtChartVal3", "TxtChartVal4" };
                    for (int s = 0; s <= 3; s++)
                    {
                        string stag = _slotTags[s];
                        var cv = slotCanvases[s];
                        DrawSlotChart(cv, stag, snap, idxLastFull, slotValNames[s]);
                        if (_stressChartsMode) ShowSlotChart(s, stag);
                    }

                    // GPU power tile
                    if (TxtGpuPower != null)
                        TxtGpuPower.Text = snap.GpuPowerW.HasValue ? $"GPU {snap.GpuPowerW.Value:F1} W" : "GPU --";

                    // RAM usage bars
                    try
                    {
                        float totalMB = _cachedTotalRamMB > 0 ? _cachedTotalRamMB : (GC.GetGCMemoryInfo().TotalAvailableMemoryBytes / 1024f / 1024f);
                        float availMB = _cachedAvailRamMB >= 0 ? _cachedAvailRamMB : 0f;
                        float usedMB  = totalMB - availMB;
                        double ramPct = totalMB > 0 ? Math.Clamp(usedMB / totalMB, 0, 1) : 0;

                        if (StressRamBar?.Parent is Border rt && rt.ActualWidth > 0)
                            StressRamBar.Width = rt.ActualWidth * ramPct;
                        string ramTotalNominal = SMDWin.Services.UnitFormat.RamTotalLabelFromMB(totalMB);
                        if (FindName("TxtKpiRamDetail") is System.Windows.Controls.TextBlock sru)
                            sru.Text = $"{usedMB/1024:F1} GB / {ramTotalNominal}";
                        if (FindName("TxtKpiRamPct") is System.Windows.Controls.TextBlock krp)
                            krp.Text = $"{ramPct*100:F0}%";
                        if (FindName("TxtKpiRamDetail") is System.Windows.Controls.TextBlock krd)
                            krd.Text = $"{usedMB/1024:F1} GB / {ramTotalNominal}";
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }

                    // VRAM bar — only used MB available (no total in TempSnapshot)
                    if (snap.GpuMemUsedMB.HasValue && snap.GpuMemUsedMB.Value > 0)
                    {
                        if (TxtGpuVram != null)
                            TxtGpuVram.Text = $"{snap.GpuMemUsedMB.Value:F0} MB used";
                        // Bar shows absolute usage scaled to a 8GB max reference
                        if (StressVramBar?.Parent is Border vt2 && vt2.ActualWidth > 0)
                            StressVramBar.Width = vt2.ActualWidth * Math.Clamp(snap.GpuMemUsedMB.Value / 8192.0, 0, 1);
                    }
                } // end if (PanelStress visible)

                if (_currentPanel == "Dashboard" || _currentPanel == "")
                try
                {

                    // CPU usage % — always read from cached counter, independent of temp sensor
                    float cpuPct = GetCpuUsagePct();
                    if (cpuPct < 0) cpuPct = 0; // counter not yet primed
                    if (cpuPct >= 0 && TxtDashCpuPct != null)
                    {
                        AnimateValue(TxtDashCpuPct, cpuPct, "", instant: true);
                        TxtDashCpuPct.Foreground = cpuPct > 85 ? _brRed
                            : cpuPct > 60 ? _brOrange
                            : _brGreen;
                        // Alert shadow handles warning state; BorderBrush left to Style
                        if (DashCpuCard != null)
                            UpdateCardAlert(DashCpuCard, cpuPct > 90, ref _cpuAlertSince);

                    if (FindName("TxtDashCpuTooltip") is System.Windows.Controls.TextBlock cpuTip)
                    {
                        var snapTip2 = _lastTempSnap;
                        var sb = new System.Text.StringBuilder();
                        sb.AppendLine($"Load: {cpuPct:F0}%");
                        if (snapTip2?.CpuFreqMHz.HasValue == true)
                            sb.AppendLine($"Freq: {snapTip2.CpuFreqMHz.Value/1000f:F2} GHz");
                        if (snapTip2?.CpuTemp.HasValue == true)
                            sb.AppendLine($"Temp: {TempUnit.Fmt(snapTip2.CpuTemp.Value)}");
                        if (snapTip2?.CpuVCoreV.HasValue == true)
                            sb.AppendLine($"VCore: {snapTip2.CpuVCoreV.Value:F3} V");
                        if (snapTip2?.CpuPowerW.HasValue == true)
                            sb.AppendLine($"Power: {snapTip2.CpuPowerW.Value:F1} W");
                        if (snapTip2?.CoreFreqs?.Count > 0)
                        {
                            sb.AppendLine("─────────────");
                            for (int ci = 0; ci < snapTip2.CoreFreqs.Count; ci++)
                                sb.AppendLine($"Core #{ci}: {snapTip2.CoreFreqs[ci]/1000f:F2} GHz");
                        }
                        cpuTip.Text = sb.ToString().TrimEnd();
                    }
                    }

                    // CPU temp on dashboard
                    if (snap.CpuTemp.HasValue && snap.CpuTemp > 0)
                    {
                        _emaCpuTemp = (float.IsNaN(_emaCpuTemp) || _emaCpuTemp < 1f) ? snap.CpuTemp.Value
                                    : TempEmaAlpha * snap.CpuTemp.Value + (1f - TempEmaAlpha) * _emaCpuTemp;
                        float ct = _emaCpuTemp;
                        _lastKnownCpuTemp = ct;
                        _lastKnownCpuTempUtc = DateTime.UtcNow;
                        if (TxtDashCpuTemp  != null) TxtDashCpuTemp.Text  = $"Temp: {TempUnit.Fmt(ct)}";
                        if (TxtDashCpuTempBig != null)
                        {
                            AnimateValue(TxtDashCpuTempBig, TempUnit.Convert(ct), "°");
                            TxtDashCpuTempBig.Foreground = ct > 85 ? _brRed : ct > 70 ? _brOrange : _brGreen;
                        }
                        if (DashCpuTempCard != null)
                            UpdateCardAlert(DashCpuTempCard, ct >= SettingsService.Current.TempWarnCpu, ref _cpuTempAlertSince);
                        // update the right column of the Hardware card (live)
                        if (FindName("TxtDashHwCpuTemp2") is System.Windows.Controls.TextBlock ct2x)
                        {
                            ct2x.Text = $"{TempUnit.Fmt(ct)}";
                            ct2x.Foreground = ct > 85 ? _brRed : ct > 70 ? _brOrange : _brGreen;
                        }
                    }
                    else
                    {
                        // Sensor unavailable — show actionable message
                        string noTempMsg = snap.Backend.StartsWith("none")
                            ? "Run as Admin for temps"
                            : "No sensor data";
                        if (TxtDashCpuTemp != null) TxtDashCpuTemp.Text = noTempMsg;
                        // Show persistent banner when sensors unavailable
                        {
                        }
                        if (TxtDashCpuTempBig != null)
                        {
                            TxtDashCpuTempBig.Text = "N/A";
                            TxtDashCpuTempBig.Foreground = _brGray;
                        }
                    }
                    if (snap.GpuTemp.HasValue && snap.GpuTemp > 0 && TxtDashGpuTempBig != null)
                    {
                        _emaGpuTemp = (float.IsNaN(_emaGpuTemp) || _emaGpuTemp < 1f) ? snap.GpuTemp.Value
                                    : TempEmaAlpha * snap.GpuTemp.Value + (1f - TempEmaAlpha) * _emaGpuTemp;
                        float gt = _emaGpuTemp;
                        _lastKnownGpuTemp = gt;
                        _lastKnownGpuTempUtc = DateTime.UtcNow;
                        AnimateValue(TxtDashGpuTempBig, TempUnit.Convert(gt), "°");
                        TxtDashGpuTempBig.Foreground = gt > 85 ? _brRed : gt > 70 ? _brOrange : _brGreen;
                        if (DashGpuTempCard != null)
                            UpdateCardAlert(DashGpuTempCard, gt >= SettingsService.Current.TempWarnGpu, ref _gpuTempAlertSince);
                        // GPU temp in the right column of Hardware
                        if (FindName("TxtDashHwGpuTemp2") is System.Windows.Controls.TextBlock gt2x)
                        {
                            gt2x.Text = $"{TempUnit.Fmt(gt)}";
                            gt2x.Foreground = gt > 85 ? _brRed : gt > 70 ? _brOrange : _brGreen;
                        }
                        if (FindName("TxtDashVramUsedLive") is System.Windows.Controls.TextBlock vramLive)
                        {
                            var vramBadge = FindName("BorderDashVramUsedLive") as System.Windows.Controls.Border;
                            if (snap.GpuMemUsedMB.HasValue && snap.GpuMemUsedMB.Value > 0)
                            {
                                vramLive.Text = $"{snap.GpuMemUsedMB.Value / 1024f:F1} GB used";
                                if (vramBadge != null) vramBadge.Visibility = Visibility.Visible;
                                else vramLive.Visibility = Visibility.Visible;
                            }
                            else
                            {
                                if (vramBadge != null) vramBadge.Visibility = Visibility.Collapsed;
                                else vramLive.Visibility = Visibility.Collapsed;
                            }
                        }
                    }
                    else if (TxtDashGpuTempBig != null)
                    {
                        bool isIntegrated = !string.IsNullOrEmpty(snap.IntegratedGpuName) && snap.IntegratedGpuName != "--";
                        if (isIntegrated && snap.CpuTemp.HasValue)
                        {
                            TxtDashGpuTempBig.Text = $"≈{TempUnit.Fmt(snap.CpuTemp.Value)}";
                            TxtDashGpuTempBig.Foreground = _brGray;
                            TxtDashGpuTempBig.ToolTip = SMDWin.Services.LanguageService.CurrentCode switch
                            {
                                "ro" => "GPU-ul integrat nu are senzor de temperatură separat — valoarea afișată e temperatura pachetului CPU, comună.",
                                "de" => "Die integrierte GPU hat keinen eigenen Temperatursensor — angezeigt wird die gemeinsame CPU-Paket-Temperatur.",
                                "fr" => "Le GPU intégré n'a pas de capteur de température séparé — la valeur affichée est la température du package CPU, partagée.",
                                _    => "Integrated GPU has no separate temperature sensor — shown value is the shared CPU package temperature.",
                            };
                        }
                        else
                        {
                            TxtDashGpuTempBig.Text = "N/A";
                            TxtDashGpuTempBig.Foreground = _brGray;
                            TxtDashGpuTempBig.ToolTip = null;
                        }
                        if (DashGpuTempCard != null) UpdateCardAlert(DashGpuTempCard, false, ref _gpuTempAlertSince);
                    }
                    // VCore + CPU Power (from LHM, available after PawnIO)
                    if (FindName("TxtDashVCore2") is System.Windows.Controls.TextBlock vc2x)
                    {
                        float vc = snap.CpuVCoreV ?? -1f;
                        vc2x.Text = vc > 0 ? $"{vc:F3} V" : "—";
                    }
                    if (FindName("TxtDashCpuPower2") is System.Windows.Controls.TextBlock pw2x)
                    {
                        float pw = snap.CpuPowerW ?? -1f;
                        pw2x.Text = pw > 0 ? $"{pw:F1} W" : "—";
                    }

                    // RAM usage
                    UpdateDashboardRam();

                    // Update GPU card (usage approximated from temp data)
                    try
                    {
                        // GPU%: LHM (snap.GpuLoadPct) is the primary source
                        float gpuPct = -1f;
                        if (_lastTempSnap?.GpuLoadPct.HasValue == true && _lastTempSnap.GpuLoadPct.Value >= 0)
                            gpuPct = _lastTempSnap.GpuLoadPct.Value;
                        else
                            gpuPct = GetGpuUsagePct();
                        if (!_gpuDiagLogged)
                        {
                            _gpuDiagLogged = true;
                            AppLogger.Info(
                                "GPU% diag: LHM.GpuLoadPct={0}, cachedGpuPct={1}, gpuCountersInit={2}, gpuCountersCount={3}, resolved gpuPct={4}",
                                _lastTempSnap?.GpuLoadPct?.ToString("F1") ?? "null",
                                _cachedGpuPct, _gpuCountersInitialized, _gpuCounters?.Count ?? -1, gpuPct);
                        }
                        if (TxtDashGpuPct != null)
                        {
                            float displayGpu = gpuPct >= 0 ? gpuPct : (_cachedGpuPct >= 0 ? _cachedGpuPct : -1f);
                            // Show 0% instead of "—" when GPU load is not available
                            float showGpu = displayGpu >= 0 ? displayGpu : 0f;
                            AnimateValue(TxtDashGpuPct, showGpu, "", instant: true);
                            // Color text based on GPU load
                            if (gpuPct >= 0)
                                TxtDashGpuPct.Foreground = gpuPct > 90 ? _brRed
                                    : gpuPct > 70 ? _brOrange
                                    : _brGreen;

                        }
                        // Alert shadow handles warning state; BorderBrush left to Style
                        if (DashGpuCard != null && gpuPct >= 0)
                            UpdateCardAlert(DashGpuCard, gpuPct > 90, ref _gpuAlertSince);
                        if (TxtDashGpuSub != null && _summary?.GpuName != null)
                            TxtDashGpuSub.Text = _summary.GpuName.Length > 28 ? _summary.GpuName[..28] + "…" : _summary.GpuName;
                        // Encode / Decode in the dashboard GPU card
                        if (FindName("TxtDashGpuEncode") is System.Windows.Controls.TextBlock dge)
                            dge.Text = _cachedGpuEncodePct >= 0 ? $"{_cachedGpuEncodePct:F0}%" : "—";
                        if (FindName("TxtDashGpuDecode") is System.Windows.Controls.TextBlock dgd)
                            dgd.Text = _cachedGpuDecodePct >= 0 ? $"{_cachedGpuDecodePct:F0}%" : "—";
                        // GPU temp inline on CPU/GPU combined card
                        if (TxtDashGpuTempInline != null && snap.GpuTemp.HasValue && snap.GpuTemp > 0)
                        {
                            float gt = snap.GpuTemp.Value;
                            TxtDashGpuTempInline.Text = $"{TempUnit.Fmt(gt)}";
                            TxtDashGpuTempInline.Foreground = gt > 85 ? _brRed : gt > 70 ? _brOrange : _brGreen;
                        }
                        // GPU load for chart:
                        // During GPU stress (ClearRenderTargetView / compute), NVIDIA LHM reports only
                        // the "3D engine" load which can be low even when GPU is fully occupied by
                        // Copy/Compute engines. Use perf counter (sum of all GPU engines) when stress
                        // is active and LHM reads low. Otherwise prefer LHM (more accurate in idle).
                        int gidx = (_chartIdx - 1) % ChartMaxPoints;
                        float gpuForChart;
                        // Prefer LHM snap; fall back to perf counter (_cachedGpuPct)
                        float gpuFromSnap = snap.GpuLoadPct.HasValue ? snap.GpuLoadPct.Value : -1f;
                        float gpuFromPerf = _cachedGpuPct >= 0 ? _cachedGpuPct : -1f;

                        bool lhmLowDuringStress = _gpuStress.IsRunning
                            && gpuFromSnap >= 0 && gpuFromSnap < 50f
                            && gpuPct > gpuFromSnap;
                        if (lhmLowDuringStress)
                            gpuForChart = gpuPct >= 0 ? gpuPct : float.NaN;
                        else if (gpuFromSnap >= 0)
                            gpuForChart = gpuFromSnap;
                        else if (gpuFromPerf >= 0)
                            gpuForChart = gpuFromPerf;  // fallback: perf counter
                        else if (_cachedGpuPct >= 0)
                            gpuForChart = _cachedGpuPct;
                        else
                            gpuForChart = float.NaN;
                        _sparkGpuHistory[gidx] = gpuForChart;
                        var gpuSparkColor = TryFindResource("GpuAccentBrush") is SolidColorBrush gpuBr
                            ? gpuBr.Color : WpfColor.FromRgb(168, 85, 247);
                        // SparkGpu now handled by DrawDashSmooth in render tick
                        try { DrawGpuLoadChart(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                    }
                    catch (Exception ex) { AppLogger.Debug(ex.Message); }

                    _dashSizeChanged = true;

                    // Update temp range labels
                    try
                    {
                    }
                    catch (Exception ex) { AppLogger.Debug(ex.Message); }

                    // Update Disk + Network activity charts
                    try
                    {
                        float netDown = _emaNetDown, netUp = _emaNetUp;
                        string netAdapterName = _lastNetAdapterName;
                        float diskRead = _emaDiskRead, diskWrite = _emaDiskWrite;
                        // _lastDiskActivePct/_lastDiskAvgMs are set by GetSystemDiskIO

                        // Disk/Net now use _chartIdx (already incremented above) to match the time interval chosen in Temp & Stress — the same
                        // ChartMaxPoints buffer
                        int didx = (_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints;
                        _dashDiskRead[didx]  = diskRead;
                        _dashDiskWrite[didx] = diskWrite;
                        // EMA aplicat in PushToQueues
                        _dashNetDown[didx]   = _emaNetDown;
                        _dashNetUp[didx]     = _emaNetUp;
                        // _dashActivityIdx kept for legacy — no longer drives draw index

                        // Update labels
                        if (TxtDashDiskActivity != null)
                        {
                            TxtDashDiskActivity.Text = FormatDiskRW(diskRead, diskWrite);
                            var (rTxt1, wTxt1) = FormatDiskRWParts(diskRead, diskWrite);
                            if (TxtDashDiskR != null) TxtDashDiskR.Text = rTxt1;
                            if (TxtDashDiskW != null) TxtDashDiskW.Text = wTxt1;
                            SyncDiskRWTextColors();
                            if (_diskTooltipTb != null)
                                _diskTooltipTb.Text = $"R: {FormatKBps(diskRead)}  W: {FormatKBps(diskWrite)}" +
                                           (_lastDiskActivePct >= 0 ? $"  Active: {_lastDiskActivePct:F0}%" : "");
                        }

                        // Storage page — Live I/O card
                        if (FindName("TxtStorageActivePct") is System.Windows.Controls.TextBlock sap)
                        {
                            sap.Text = $"{_lastDiskActivePct:F0}%";
                            sap.Foreground = _lastDiskActivePct > 90 ? _brRed
                                : _lastDiskActivePct > 70 ? _brOrange
                                : _brGreen;
                        }
                        if (FindName("TxtStorageAvgMs") is System.Windows.Controls.TextBlock sam)
                            sam.Text = _lastDiskAvgMs < 1 ? "<1" : $"{_lastDiskAvgMs:F1}";
                        if (FindName("TxtStorageLiveRead")  is System.Windows.Controls.TextBlock slr)
                            slr.Text = FormatKBps(_emaDiskRead);
                        if (FindName("TxtStorageLiveWrite") is System.Windows.Controls.TextBlock slw)
                            slw.Text = FormatKBps(_emaDiskWrite);
                        if (TxtDashNetDown != null) TxtDashNetDown.Text = $"↓ {FormatKBps(netDown)}";
                        if (FindName("TxtDashNetTooltip2") is System.Windows.Controls.TextBlock ntt)
                            ntt.Text = $"↓ Download: {FormatKBps(netDown)}\n↑ Upload: {FormatKBps(netUp)}";
                        if (TxtDashNetUp   != null) TxtDashNetUp.Text   = $"↑ {FormatKBps(netUp)}";
                        SyncNetDownUpTextColors();
                        if (_lastWifi.IsConnected)
                        {
                            if (FindName("TxtDashNetAdapter") is System.Windows.Controls.TextBlock netAdTb)
                                netAdTb.Text = $"{_lastWifi.Ssid}  {_lastWifi.RssiBar} {_lastWifi.Rssi} dBm" + (string.IsNullOrEmpty(_lastWifi.Band) ? "" : $" · {_lastWifi.Band}");
                        }
                        if (TxtDashNetAdapter != null && !string.IsNullOrEmpty(netAdapterName))
                            TxtDashNetAdapter.Text = netAdapterName.Length > 20 ? netAdapterName[..20] + "…" : netAdapterName;

                        // The draws are in UpdateDashboardLiveCardsInternal (clockTimer 1s) — no duplicate drawing here, to avoid flickering
                    }
                    catch (Exception ex) { AppLogger.Debug(ex.Message); }

                    _dashSizeChanged = true;
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }

                if (SettingsService.Current.EnableNotifications)
                {
                    Title = snap.CpuTemp > SettingsService.Current.TempWarnCpu
                        ? $"CPU {TempUnit.Fmt(snap.CpuTemp)} — SMD Win"
                        : "SMD Win — System & Monitoring Data";
                }
                _tempFailCount = 0; // reset on success
            }
            catch
            {
                _tempFailCount++;
                if (_tempFailCount >= TempFailThreshold)
                {
                    // TempReader got stuck — reinitialize in the background
                    _tempFailCount = 0;
                    _ = Task.Run(() =>
                    {
                        try { _tempReader?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                        _tempReader = null;
                        try { _tempReader = new SMDWin.Services.TempReader(); } catch (Exception logEx) { AppLogger.Warning(logEx, "_tempReader = new SMDWin.Services.TempReader();"); }
                        _ = Dispatcher.InvokeAsync(() =>
                        {
                            if (TxtTempBackend != null)
                                if (TxtTempBackend != null) TxtTempBackend.Text = _tempReader != null
                                    ? $"Sensor: {_tempReader.Backend} (restarted)"
                                    : "Sensor unavailable — run as Admin";
                        });
                    });
                }
            }
            // Update tray icon with live CPU temp + load
            SMDWin.Services.UiStallLogger.Mark("TempTick:tray");
            try { UpdateTrayIconWithTemp(snap.CpuTemp, snap.GpuTemp); } catch (Exception logEx) { AppLogger.Warning(logEx, "UpdateTrayIconWithTemp(snap.CpuTemp, snap.GpuTemp);"); }

            // ── Extra Windows notifications ────────────────────────────────
            try
            {
                var _tSnapNotif = _lastThrottle;
                bool throttled = _tSnapNotif?.IsThrottled == true;

                bool throttledRaw = throttled
                    && _tSnapNotif!.Reason != SMDWin.Services.ThrottleReason.PowerLimit
                    && _tSnapNotif.Reason != SMDWin.Services.ThrottleReason.None;
                if (throttledRaw)
                {
                    if (_tSnapNotif!.Reason == _throttleCandidateReason)
                        _throttleConsecutiveTicks++;
                    else
                    {
                        _throttleCandidateReason = _tSnapNotif.Reason;
                        _throttleConsecutiveTicks = 1;
                    }
                }
                else
                {
                    _throttleCandidateReason = SMDWin.Services.ThrottleReason.None;
                    _throttleConsecutiveTicks = 0;
                }
                bool throttleConfirmed = throttledRaw && _throttleConsecutiveTicks >= ThrottleConfirmTicks;

                if (throttleConfirmed && _throttleConsecutiveTicks == ThrottleConfirmTicks)
                {
                    AppLogger.Warning(
                        "S2-DIAG Throttle CONFIRMED: reason={0} freqMHz={1:F0} loadPct={2:F0} " +
                        "after {3} consecutive ticks (threshold={4})",
                        _tSnapNotif?.Reason.ToString() ?? "?", _tSnapNotif?.FreqMHz ?? -1,
                        snap?.CpuLoadPct ?? -1, _throttleConsecutiveTicks, ThrottleConfirmTicks);
                }

                string throttleReason = _tSnapNotif?.ReasonLabel ?? "Thermal/Power limit";
                CheckThrottleNotif(throttleConfirmed, throttleReason);
                if (throttleConfirmed && _tSnapNotif != null)
                {
                    int throttleSeverity =
                        (_tSnapNotif.Reason == SMDWin.Services.ThrottleReason.BdProchot ||
                         _tSnapNotif.Reason == SMDWin.Services.ThrottleReason.Thermal) ? 2 : 1;
                    string throttleTooltip = string.IsNullOrEmpty(_tSnapNotif.ReasonDetail)
                        ? _tSnapNotif.ReasonLabel
                        : $"{_tSnapNotif.ReasonLabel} — {_tSnapNotif.ReasonDetail}";
                    UpdateSidebarBadge("Temp", 1, throttleTooltip, throttleSeverity);
                    _badgeTempLastSeenUtc = DateTime.UtcNow;
                    // Notify only once per episode, not on EVERY tick while the condition persists (otherwise the Notification Center fills
                    // with dozens of identical entries during a single real 2-minute PROCHOT). The exact confirmation threshold
                    // (== ThrottleConfirmTicks, not >=) marks the candidate->confirmed transition only once; the FOLLOWING ticks still update
                    // the badge (above), they just do not add a new Notification Center entry.
                    if (_throttleConsecutiveTicks == ThrottleConfirmTicks)
                    {
                        SMDWin.Services.NotificationCenter.Add(SMDWin.Services.NotifCategory.Throttle,
                            SMDWin.Services.NotifSeverity.Warning,
                            throttleTooltip);
                    }
                }

                // Disk space C: — check every ~50 ticks (~100s) to avoid DriveInfo overhead
                if (_trayTickCount % 50 == 3) CheckDiskSpaceNotif();

                // Network unusual activity — notification disabled (too many false positives on normal downloads)
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }

            // Update title bar live metrics
            try
            {
                float tbCpu = snap!.CpuTemp.HasValue ? GetCpuUsagePct() : -1;
                var (tbRamMB, _) = SMDWin.Services.WmiCache.Instance.GetRamUsage();
                float tbRam = tbRamMB > 0 ? tbRamMB / 1024f : -1;
                float tbGpu = snap.GpuLoadPct ?? -1;
                if (tbCpu >= 0 || tbRam >= 0)
                    UpdateTitleBarMetrics(Math.Max(0, tbCpu), Math.Max(0, tbRam), tbGpu);
            } catch (Exception ex) { AppLogger.Warning(ex, "OnTempTick UI update failed"); }

            // Update Fan Speeds card
            SMDWin.Services.UiStallLogger.Mark("TempTick:fans");
            try { UpdateFanSpeedsCard(snap!); } catch (Exception ex) { AppLogger.Debug(ex.Message); }

            // Push live data to compact widget (if open)
            try
            {
                if (_compactWidget != null)
                {
                    float ramPct = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                        ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f)
                        : -1f;
                    int didx = (_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints;
                    float diskR = _dashDiskRead[didx];
                    float diskW = _dashDiskWrite[didx];
                    _compactWidget.PushData(
                        cpuPct:      _cachedCpuPct,
                        gpuPct:      _cachedGpuPct,
                        ramPct:      ramPct,
                        netUp:       _emaNetUp,
                        netDown:     _emaNetDown,
                        diskRead:    diskR,
                        diskWrite:   diskW,
                        cpuTemp:     snap!.CpuTemp,
                        gpuTemp:     snap.GpuTemp,
                        cpuFreqMHz:  snap.CpuFreqMHz ?? (_lastCpuFreqMHz > 0 ? _lastCpuFreqMHz : (float?)null));
                }

                if (_traySensorIcons.Count > 0)
                {
                    float ramPctTray = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                        ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f)
                        : -1f;
                    UpdateTraySensorIcons(
                        cpuPct:     _cachedCpuPct,
                        gpuPct:     _cachedGpuPct,
                        ramPct:     ramPctTray,
                        cpuTemp:    snap!.CpuTemp,
                        gpuTemp:    snap.GpuTemp,
                        cpuFreqMHz: snap.CpuFreqMHz ?? (_lastCpuFreqMHz > 0 ? _lastCpuFreqMHz : (float?)null));
                }

                try { SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning); }
                catch (Exception ex) { AppLogger.Debug($"TaskBadgeStress poll: {ex.Message}"); }
            } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }
            finally
            {
                _tempTickBusy = false;
            }
        }
    }
}
